// AUTO-GENERATED from marketing/content-drafts/composer-bios.md — do not hand-edit.
export const BIOS = {"J. S. Bach":"<p>Johann Sebastian Bach (born 31 March 1685 in Eisenach, Germany; died 28 July 1750 in Leipzig) was a German composer of the late Baroque period, widely regarded as one of the greatest composers in the history of Western music. He is especially celebrated for his mastery of counterpoint and his harmonic innovation.</p><p>His best‑known works include the <em>Brandenburg Concertos</em>, <em>The Well‑Tempered Clavier</em>, the <em>Goldberg Variations</em> and the <em>Mass in B minor</em>. On DoReDog you can play <strong>359</strong> of his pieces — the largest collection in the library — in colour‑coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Sebastian_Bach\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Franz Schubert":"<p>Franz Peter Schubert (born 31 January 1797 in Vienna; died 19 November 1828 in Vienna) was an Austrian composer of the late Classical and early Romantic periods. Extraordinarily prolific, he wrote more than 1,000 works in his short life and is remembered above all as a master of the Lied — the German art song.</p><p>His most famous works include the \"Unfinished\" Symphony (No. 8), the \"Great\" Symphony (No. 9), the song \"Erlkönig\" and the String Quintet in C major. DoReDog has <strong>103</strong> Schubert pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Franz_Schubert\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johannes Brahms":"<p>Johannes Brahms (born 7 May 1833 in Hamburg; died 3 April 1897 in Vienna) was a German composer of the mid‑Romantic period. He is remembered for extending the structural principles of Beethoven while upholding traditional musical forms against the modernist currents of his time.</p><p>His notable works include the Symphony No. 1 in C minor, <em>A German Requiem</em>, the <em>Hungarian Dances</em> and the Violin Concerto in D major. You'll find <strong>95</strong> of his pieces on DoReDog. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johannes_Brahms\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ludwig van Beethoven":"<p>Ludwig van Beethoven (born December 1770 in Bonn; died 26 March 1827 in Vienna) was a German composer whose work drove the transition from the Classical to the Romantic era. He is regarded as one of the greatest composers in the history of Western music, expanding forms such as the symphony, piano sonata and string quartet.</p><p>His best‑known works include the Symphony No. 5, the Symphony No. 9, the \"Moonlight\" Sonata and his opera <em>Fidelio</em>. DoReDog has <strong>70</strong> Beethoven pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ludwig_van_Beethoven\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","W. A. Mozart":"<p>Wolfgang Amadeus Mozart (born 27 January 1756 in Salzburg; died 5 December 1791 in Vienna, aged 35) was an Austrian composer of the Classical period. Despite his short life he completed more than 800 works and is regarded as one of the greatest composers in Western music.</p><p>His most famous works include the operas <em>The Marriage of Figaro</em>, <em>Don Giovanni</em> and <em>The Magic Flute</em>, and his unfinished <em>Requiem</em>. On DoReDog you can play <strong>65</strong> of his pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Wolfgang_Amadeus_Mozart\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","G. F. Handel":"<p>George Frideric Handel (born 5 March 1685 in Halle; died 14 April 1759 in London) was a German‑born Baroque composer who became a naturalised British subject in 1727. He is celebrated for bringing Italian opera to its highest development and for creating the genre of English oratorio.</p><p>His best‑known works include <em>Messiah</em> (with its \"Hallelujah\" chorus), the <em>Water Music</em>, <em>Music for the Royal Fireworks</em> and <em>Zadok the Priest</em>. DoReDog has <strong>58</strong> Handel pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/George_Frideric_Handel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Frédéric Chopin":"<p>Frédéric Chopin (born 1 March 1810 in Żelazowa Wola, near Warsaw; died 17 October 1849 in Paris, aged 39) was a Polish composer of the early Romantic period, whose piano technique was without equal in his generation. He wrote almost exclusively for the piano.</p><p>His Nocturnes, Mazurkas, Polonaises and Études remain cornerstones of the piano repertoire. You'll find <strong>52</strong> Chopin pieces on DoReDog, written out in colour‑coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Fr%C3%A9d%C3%A9ric_Chopin\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Robert Schumann":"<p>Robert Schumann (born 8 June 1810 in Zwickau; died 29 July 1856 in Bonn) was a German composer, pianist and music critic whose compositions typify the spirit of the Romantic era in German music.</p><p>His notable works include <em>Carnaval</em>, <em>Kreisleriana</em>, the song cycle <em>Dichterliebe</em> and the Piano Concerto in A minor. DoReDog has <strong>50</strong> Schumann pieces in letter notes — including several from his <em>Album for the Young</em>, written for beginners. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Robert_Schumann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Erik Satie":"<p>Erik Satie (born 17 May 1866 in Honfleur, Normandy; died 1 July 1925 in Paris) was a French composer of the late 19th and early 20th centuries. He is credited with steering a new generation of French composers toward a leaner, more spare musical style.</p><p>His best‑known works include the three <em>Gymnopédies</em>, the <em>Gnossiennes</em>, the ballet <em>Parade</em> and <em>Socrate</em>. DoReDog has <strong>27</strong> Satie pieces — his slow, hypnotic <em>Gymnopédies</em> are among the most beginner‑friendly in the whole library. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Erik_Satie\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Georges Bizet":"<p>Georges Bizet (born 25 October 1838 in Paris; died 3 June 1875 in Bougival, near Paris) was a French composer of the Romantic era. He is best remembered for his opera <em>Carmen</em>, now one of the most frequently performed operas in the world — though he died just three months after its premiere, before its success.</p><p>His other works include the <em>L'Arlésienne</em> suite, the opera <em>Les pêcheurs de perles</em> and the <em>Symphony in C</em>. DoReDog has <strong>23</strong> Bizet pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Georges_Bizet\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Joseph Haydn":"<p>Franz Joseph Haydn (born 31 March 1732 in Rohrau, Austria; died 31 May 1809 in Vienna) was an Austrian composer of the Classical period, often called the \"Father of the Symphony\" for his central role in developing the symphony, the string quartet and sonata form.</p><p>His best‑known works include the \"Surprise\" Symphony (No. 94), the \"London\" Symphony (No. 104) and the oratorio <em>The Creation</em>. DoReDog has <strong>19</strong> Haydn pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Joseph_Haydn\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Scott Joplin":"<p>Scott Joplin (born around 1868 in Texas — his exact birth date and place are uncertain; died 1 April 1917 in New York City) was an American composer and pianist known as the \"King of Ragtime.\" He composed more than 40 ragtime pieces and helped elevate ragtime to a respected art form.</p><p>His most famous works include the \"Maple Leaf Rag,\" \"The Entertainer\" and the opera <em>Treemonisha</em>. DoReDog has <strong>19</strong> Joplin rags in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Scott_Joplin\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Gabriel Fauré":"<p>Gabriel Urbain Fauré (born 12 May 1845 in Pamiers, France; died 4 November 1924 in Paris) was a French composer whose style bridged the end of Romanticism and the modernism of the early 20th century. He was one of the foremost French composers of his generation.</p><p>His best‑known works include the <em>Pavane</em>, the <em>Requiem</em>, his Nocturnes for piano and the song \"Clair de lune.\" You'll find <strong>16</strong> Fauré pieces on DoReDog. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Gabriel_Faur%C3%A9\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","P. I. Tchaikovsky":"<p>Pyotr Ilyich Tchaikovsky (born 7 May 1840 in Votkinsk, Russia; died 6 November 1893 in Saint Petersburg) was a Russian composer of the Romantic period — the first Russian composer whose music made a lasting impression internationally.</p><p>His most famous works include the ballets <em>Swan Lake</em> and <em>The Nutcracker</em>, the <em>1812 Overture</em> and his First Piano Concerto. DoReDog has <strong>11</strong> Tchaikovsky pieces in letter notes, including several from his <em>Album for the Young</em>. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Pyotr_Ilyich_Tchaikovsky\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Edvard Grieg":"<p>Edvard Hagerup Grieg (born 15 June 1843 in Bergen, Norway; died 4 September 1907 in Bergen) was a Norwegian composer of the Romantic era whose use of Norwegian folk music brought his country's music to international fame.</p><p>His best‑known works include the Piano Concerto in A minor, the <em>Peer Gynt</em> music (including \"Morning Mood\" and \"In the Hall of the Mountain King\"), the <em>Holberg Suite</em> and the <em>Lyric Pieces</em> for piano. DoReDog has <strong>10</strong> Grieg pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Edvard_Grieg\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Claude Debussy":"<p>Claude Debussy (born 22 August 1862 in Saint‑Germain‑en‑Laye, France; died 25 March 1918 in Paris) was a French composer often described as the first Impressionist composer — a label he himself rejected. He developed an innovative harmonic language that broke away from 19th‑century German tradition.</p><p>His best‑known works include <em>Prélude à l'après‑midi d'un faune</em>, <em>La mer</em>, the opera <em>Pelléas et Mélisande</em> and the beloved \"Clair de lune\" from his <em>Suite bergamasque</em>. DoReDog has <strong>8</strong> Debussy pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Claude_Debussy\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Franz Liszt":"<p>Franz Liszt (born 22 October 1811 in Doborján, Kingdom of Hungary — now Raiding, Austria; died 31 July 1886 in Bayreuth) was a Hungarian composer and pianist of the Romantic period, one of the most prolific and influential composers of his era and a pioneer of the symphonic poem.</p><p>His best‑known works include the <em>Hungarian Rhapsodies</em>, <em>Années de pèlerinage</em>, the <em>Transcendental Études</em> and the Piano Sonata in B minor. DoReDog has <strong>8</strong> Liszt pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Franz_Liszt\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Felix Mendelssohn":"<p>Felix Mendelssohn (born 3 February 1809 in Hamburg; died 4 November 1847 in Leipzig) was a German composer of the early Romantic era. He was central to reviving interest in J. S. Bach's music, notably through his 1829 performance of the <em>St Matthew Passion</em>.</p><p>His best‑known works include the String Octet, the incidental music for <em>A Midsummer Night's Dream</em> (including the famous \"Wedding March\") and the <em>Scottish Symphony</em>. DoReDog has <strong>11</strong> Mendelssohn pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Felix_Mendelssohn\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Domenico Scarlatti":"<p>Domenico Scarlatti (born 26 October 1685 in Naples; died 23 July 1757 in Madrid) was an Italian composer of the Baroque period whose work also influenced the emerging Classical style. He is known mainly for his 555 keyboard sonatas.</p><p>Those sonatas — inventive, brilliant and idiomatic to the keyboard — are the body of work for which he is celebrated. DoReDog has <strong>14</strong> Scarlatti pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Domenico_Scarlatti\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Augusta Mary Anne Holmès":"<p>Augusta Mary Anne Holmès (born 16 December 1847 in Paris; died 28 January 1903 in Versailles) was a French Romantic composer, born to Irish parents and naturalised French in 1871. A pioneering woman composer, she wrote four operas — largely inspired by Wagner — as well as substantial orchestral and vocal works.</p><p>Her best‑known works include the opera <em>La Montagne noire</em>, the <em>Ode triomphale</em> and the symphonic poems <em>Irlande</em> and <em>Andromède</em>. With <strong>66</strong> pieces, she has one of the largest collections on DoReDog. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Augusta_Holm%C3%A8s\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Sergei Rachmaninoff":"<p>Sergei Vasilyevich Rachmaninoff (born 1 April 1873 in Semyonovo, Russia; died 28 March 1943 in Beverly Hills, California) was a Russian composer and pianist, one of the last great representatives of Romanticism in Russian classical music and one of the finest pianists of his era.</p><p>His best‑known works include the Piano Concerto No. 2, the Prelude in C‑sharp minor and the <em>Rhapsody on a Theme of Paganini</em>. DoReDog has <strong>10</strong> Rachmaninoff pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Sergei_Rachmaninoff\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Edward Elgar":"<p>Sir Edward Elgar (born 2 June 1857 in Lower Broadheath, near Worcester, England; died 23 February 1934 in Little Malvern) was an English composer of the late Romantic period whose orchestral works entered the international concert repertoire.</p><p>His best‑known works include the <em>Enigma Variations</em>, <em>The Dream of Gerontius</em>, the <em>Pomp and Circumstance Marches</em> and the Violin Concerto. DoReDog has <strong>10</strong> Elgar pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Edward_Elgar\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Josephine Lang":"<p>Josephine Caroline Lang (born 14 March 1815 in Munich; died 2 December 1880 in Tübingen) was a German composer of the Romantic era who specialised in the Lied — the German art song. Both Felix Mendelssohn and Ferdinand Hiller took pains to help her study composition properly and used their connections to get her music published.</p><p>She wrote numerous songs and piano works across more than 40 opus numbers. DoReDog has <strong>41</strong> Lang pieces in letter notes — one of the larger collections in the library. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Josephine_Lang\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johanna Kinkel":"<p>Johanna Kinkel (née Mockel; born 8 July 1810 in Bonn; died 15 November 1858 in London) was a German composer, writer, pedagogue and revolutionary who took an active part in the 1848 revolutionary movement before emigrating to London.</p><p>Her works include the choral <em>Die Vogelkantate</em> (\"The Bird Cantata,\" Op. 1) and the opera <em>Otto der Schütz</em>. DoReDog has <strong>39</strong> Kinkel pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johanna_Kinkel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Robert Franz":"<p>Robert Franz (born Robert Franz Julius Knauth; 28 June 1815 in Halle; died 24 October 1892 in Halle) was a German composer of the Romantic era who specialised almost entirely in the Lied, writing around 250 songs. His work was admired by Mendelssohn, Liszt and Schumann, and he also edited music by Bach and Handel.</p><p>DoReDog has <strong>37</strong> Robert Franz pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Robert_Franz\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Liza Lehmann":"<p>Liza Lehmann (born Elisabetha Nina Mary Frederica Lehmann; 11 July 1862 in London; died 19 September 1918 in Pinner, Middlesex) was an English composer and singer, recognised as one of England's foremost female song composers at the turn of the 20th century. She served as the first president of the Society of Women Musicians.</p><p>Her best‑known works include the song cycle <em>In a Persian Garden</em>, <em>The Daisy Chain</em> and the song \"There are Fairies at the Bottom of Our Garden.\" DoReDog has <strong>29</strong> Lehmann pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Liza_Lehmann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Fanny (Mendelssohn) Hensel":"<p>Fanny Hensel (née Mendelssohn; born 14 November 1805 in Hamburg; died 14 May 1847 in Berlin) was a German composer of the early Romantic era and the elder sister of Felix Mendelssohn. She composed prolifically — over 450 works, including more than 125 pieces for solo piano and over 250 Lieder — yet remained largely unpublished in her lifetime because of the social conventions that restricted women's public musical careers.</p><p>DoReDog has <strong>18</strong> of her pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Fanny_Mendelssohn\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Friedrich Burgmüller":"<p>Friedrich Burgmüller (born Johann Friedrich Franz Burgmüller; 4 December 1806 in Regensburg; died 13 February 1874 in Paris) was a German composer of the Romantic era, best known for his three collections of piano études written as teaching pieces.</p><p>His <em>25 Easy and Progressive Studies</em> (Op. 100) are among the most widely used beginner piano pieces ever written. DoReDog has <strong>19</strong> Burgmüller pieces in letter notes — many ideal for early learners. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Friedrich_Burgm%C3%BCller\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Moritz Moszkowski":"<p>Moritz Moszkowski (born 23 August 1854 in Breslau, then Prussia, now Wrocław, Poland; died 4 March 1925 in Paris) was a German‑Polish composer and pianist of the Romantic era, celebrated in his day as a master pianist and a writer of brilliant piano miniatures.</p><p>His best‑known works include the <em>Spanish Dances</em> (Op. 12) and the <em>Études de Virtuosité</em> (Op. 72). DoReDog has <strong>19</strong> Moszkowski pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Moritz_Moszkowski\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Cécile Chaminade":"<p>Cécile Chaminade (born 8 August 1857 in Paris; died 13 April 1944 in Monte Carlo) was a French composer of the Romantic era. In 1913 she became the first female composer to be awarded the Légion d'Honneur.</p><p>Her best‑known works include the <em>Concertino</em> for flute and orchestra — her most popular piece today — and the \"Scarf Dance.\" DoReDog has <strong>16</strong> Chaminade pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/C%C3%A9cile_Chaminade\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Lili Boulanger":"<p>Lili Boulanger (born Marie‑Juliette Boulanger; 21 August 1893 in Paris; died 15 March 1918 in Mézy‑sur‑Seine, aged 24) was a French composer associated with the Symbolist and Impressionist movements. In 1913 she became the first woman to win the Grand Prix de Rome for composition, with her cantata <em>Faust et Hélène</em>.</p><p>Her other works include <em>D'un matin de printemps</em> and the song cycle <em>Clairières dans le ciel</em>. DoReDog has <strong>16</strong> Boulanger pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Lili_Boulanger\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Pachelbel":"<p>Johann Pachelbel (baptised September 1653 in Nuremberg; died early March 1706 in Nuremberg) was a German composer of the middle Baroque era. He is remembered above all for the <em>Canon in D</em>, and was historically important for his contributions to the chorale prelude and the fugue.</p><p>DoReDog has <strong>4</strong> Pachelbel pieces in letter notes — including the ever‑popular Canon in D. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Pachelbel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Antonio Vivaldi":"<p>Antonio Lucio Vivaldi (born 4 March 1678 in Venice; died 28 July 1741 in Vienna) was an Italian composer of the Baroque era who did much to consolidate the solo concerto form. He is best known for <em>The Four Seasons</em>.</p><p>DoReDog has <strong>2</strong> Vivaldi pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Antonio_Vivaldi\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Peter Cornelius":"<p>Peter Cornelius (born Carl August Peter Cornelius; 24 December 1824 in Mainz; died 26 October 1874 in Mainz) was a German composer of the Romantic period. He is best known for his comic opera <em>Der Barbier von Bagdad</em> (\"The Barber of Baghdad\") and for his <em>Weihnachtslieder</em> (Christmas songs), especially \"Die Könige\" (\"The Three Kings\").</p><p>DoReDog has <strong>25</strong> Cornelius pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Peter_Cornelius\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Clara Mathilda Faisst":"<p>Clara Mathilda Faisst (born 22 June 1872 in Karlsruhe; died 22 November 1948 in Karlsruhe) was a German late‑Romantic composer, pianist and writer. She composed over 100 works — including a Violin Sonata, songs with piano and choral pieces — noted for their expressive melody and rich harmony.</p><p>DoReDog has <strong>25</strong> Faisst pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Clara_Faisst\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Corona Schröter":"<p>Corona Schröter (born Corona Elisabeth Wilhelmine Schröter; 14 January 1751 in Guben; died 23 August 1802 in Ilmenau) was a German singer, actress and composer of the Classical era, active in Goethe's circle at Weimar. She created the title role in Goethe's <em>Iphigenie auf Tauris</em> and composed incidental music for his <em>Die Fischerin</em>, and published two collections of Lieder setting texts by Goethe and Schiller.</p><p>DoReDog has <strong>25</strong> Schröter pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Corona_Schr%C3%B6ter\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Pauline Viardot":"<p>Pauline Viardot (born Michelle Ferdinande Pauline García; 18 July 1821 in Paris; died 18 May 1910 in Paris) was a French mezzo‑soprano, composer and teacher of Spanish descent, one of the leading singers of the 19th century. She created the role of Fidès in Meyerbeer's <em>Le prophète</em> and composed several salon operas, including <em>Cendrillon</em>.</p><p>DoReDog has <strong>20</strong> Viardot pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Pauline_Viardot\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Mathilde Kralik":"<p>Mathilde Kralik (born Mathilde Aloisia Kralik von Meyrswalden; 3 December 1857 in Linz; died 8 March 1944 in Vienna) was an Austrian composer whose works were performed at the Musikverein and other major Viennese venues. Her output includes the fairy‑tale opera <em>Blume und Weissblume</em>, a Symphony in F minor, a Violin Concerto and much sacred, chamber and vocal music.</p><p>DoReDog has <strong>17</strong> Kralik pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Mathilde_Kralik\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Charles Villiers Stanford":"<p>Sir Charles Villiers Stanford (born 30 September 1852 in Dublin; died 29 March 1924 in London) was an Anglo‑Irish composer of the late Romantic era. He is remembered as a hugely influential composition teacher at the Royal College of Music — his pupils included Gustav Holst and Ralph Vaughan Williams — as well as for his own church choral works and his <em>Irish Symphony</em> (No. 3).</p><p>DoReDog has <strong>17</strong> Stanford pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Charles_Villiers_Stanford\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Peter Warlock":"<p>Peter Warlock — the pen name of Philip Arnold Heseltine (born 30 October 1894 in London; died 17 December 1930 in London) — was a British composer of the early 20th century, best known for his songs and other vocal music and for the orchestral <em>Capriol Suite</em>. He was also a pioneering early‑music scholar who transcribed hundreds of early English works.</p><p>DoReDog has <strong>19</strong> Warlock pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Peter_Warlock\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Isaac Albéniz":"<p>Isaac Albéniz (born Isaac Manuel Francisco Albéniz y Pascual; 29 May 1860 in Camprodon, Catalonia; died 18 May 1909 in Cambo‑les‑Bains, France) was a Spanish composer of the post‑Romantic era who wove Spanish folk idioms into his piano music. His best‑known works include the suite <em>Iberia</em> and \"Asturias (Leyenda).\"</p><p>DoReDog has <strong>4</strong> Albéniz pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Isaac_Alb%C3%A9niz\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Muzio Clementi":"<p>Muzio Clementi (born 23 January 1752 in Rome; died 10 March 1832 in Evesham, England) was an Italian‑born composer of the Classical period who spent most of his career in England. Sometimes called the \"Father of the Piano,\" he was among the first to write specifically for the piano's capabilities. His best‑known works include the <em>Gradus ad Parnassum</em> studies and the Six Sonatinas, Op. 36.</p><p>DoReDog has <strong>3</strong> Clementi pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Muzio_Clementi\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Hugo Wolf":"<p>Hugo Wolf (born 13 March 1860 in Windischgrätz, then Austria, now Slovenj Gradec, Slovenia; died 22 February 1903 in Vienna) was an Austrian composer of the late Romantic era, especially noted for his art songs (Lieder), to which he brought a concentrated expressive intensity unique in his time.</p><p>His best‑known works include the <em>Mörike‑Lieder</em>, <em>Eichendorff‑Lieder</em> and <em>Goethe‑Lieder</em>, along with the <em>Italian Serenade</em>. DoReDog has <strong>15</strong> Wolf pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Hugo_Wolf\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","John Philip Sousa":"<p>John Philip Sousa (born 6 November 1854 in Washington, D.C.; died 6 March 1932 in Reading, Pennsylvania) was an American composer and conductor of the late Romantic era, known as \"The March King.\"</p><p>His best‑known works include \"The Stars and Stripes Forever,\" \"Semper Fidelis\" and \"The Washington Post.\" DoReDog has <strong>10</strong> Sousa marches in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/John_Philip_Sousa\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Anton Webern":"<p>Anton Webern (born 3 December 1883 in Vienna; died 15 September 1945 in Mittersill, Austria) was an Austrian composer of the 20th century. Together with Arnold Schoenberg and Alban Berg, he formed the core of the Second Viennese School, and is known for his concise atonal and twelve‑tone works.</p><p>DoReDog has <strong>10</strong> Webern pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Anton_Webern\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Alexander Scriabin":"<p>Alexander Nikolayevich Scriabin (born 6 January 1872 in Moscow; died 27 April 1915 in Moscow) was a Russian composer and pianist, widely considered the primary Russian Symbolist composer, who developed a highly dissonant musical language that moved beyond traditional tonality.</p><p>His best‑known works include <em>The Poem of Ecstasy</em>, <em>Prometheus: The Poem of Fire</em> and his ten piano sonatas. DoReDog has <strong>8</strong> Scriabin pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Alexander_Scriabin\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Stephen Foster":"<p>Stephen Collins Foster (born 4 July 1826 in Lawrenceville, Pennsylvania; died 13 January 1864 in New York City) was an American songwriter of the 19th century, known as \"the father of American music\" and the first American to make songwriting a full‑time profession.</p><p>His best‑known songs include \"Oh! Susanna,\" \"Camptown Races\" and \"Beautiful Dreamer.\" DoReDog has <strong>9</strong> Foster pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Stephen_Foster\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Amy Marcy Beach":"<p>Amy Beach (born Amy Marcy Cheney; 5 September 1867 in Henniker, New Hampshire; died 27 December 1944 in New York City) was an American composer and pianist of the Romantic era — the first successful American female composer of large‑scale art music. Her \"Gaelic\" Symphony was the first symphony composed and published by an American woman.</p><p>DoReDog has <strong>9</strong> Beach pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Amy_Beach\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Samuel Coleridge-Taylor":"<p>Samuel Coleridge‑Taylor (born 15 August 1875 in London; died 1 September 1912 in Croydon) was a British composer of the late Romantic era who won international fame with his cantatas based on Longfellow's <em>The Song of Hiawatha</em> — above all <em>Hiawatha's Wedding Feast</em>.</p><p>DoReDog has <strong>8</strong> Coleridge‑Taylor pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Samuel_Coleridge-Taylor\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ernest Chausson":"<p>Ernest Chausson (born Amédée‑Ernest Chausson; 20 January 1855 in Paris; died 10 June 1899 near Paris) was a French composer of the Romantic era whose music bridged the ripe Romanticism of Franck and the emerging Impressionism of Debussy. His best‑known works include the <em>Poème</em> for violin and orchestra, the opera <em>Le roi Arthus</em> and his Symphony in B‑flat.</p><p>DoReDog has <strong>12</strong> Chausson pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ernest_Chausson\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","George Butterworth":"<p>George Butterworth (born 12 July 1885 in London; died 5 August 1916 at Pozières, France) was an English composer of the early 20th century, remembered above all for his orchestral idyll <em>The Banks of Green Willow</em> and his settings of A. E. Housman's <em>A Shropshire Lad</em>. He was killed in action during the First World War.</p><p>DoReDog has <strong>12</strong> Butterworth pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/George_Butterworth\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Maria Theresia von Paradis":"<p>Maria Theresia von Paradis (born 15 May 1759; died 1 February 1824) was an Austrian pianist and composer of the Classical era who lost her sight in early childhood. A celebrated performer who toured internationally, she later founded a music school in Vienna, and Mozart is thought to have composed a piano concerto for her.</p><p>DoReDog has <strong>10</strong> Paradis pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Maria_Theresia_von_Paradis\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Marie Jaëll":"<p>Marie Jaëll (born Marie Trautmann; 17 August 1846 in Steinseltz, France; died 4 February 1925 in Paris) was a French composer, pianist and teacher of the Romantic era. She was the first pianist to perform all of Beethoven's piano sonatas in Paris, and developed an influential piano method grounded in the physiology of touch that is still used today.</p><p>DoReDog has <strong>16</strong> Jaëll pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Marie_Ja%C3%ABll\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Jan Ladislav Dussek":"<p>Jan Ladislav Dussek (born 12 February 1760 in Čáslav, Bohemia; died 20 March 1812 in Saint‑Germain‑en‑Laye, France) was a Czech composer and pianist of the Classical period. One of the first piano virtuosos to tour widely across Europe, he was among the most admired pianists before Beethoven's rise, and his forward‑looking piano writing anticipated the Romantic era.</p><p>DoReDog has <strong>13</strong> Dussek pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Jan_Ladislav_Dussek\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Teodoro Cottrau":"<p>Teodoro Cottrau (born 7 December 1827 in Naples; died 30 March 1879 in Naples) was an Italian composer, lyricist and music publisher of the 19th century who did much to preserve and popularise Neapolitan song. He is best known for his 1850 arrangement of \"Santa Lucia.\"</p><p>DoReDog has <strong>14</strong> Cottrau pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Teodoro_Cottrau\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Clémence de Grandval":"<p>Clémence de Grandval (born Marie Félicie Clémence de Reiset; 21 January 1828 in Saint‑Rémy‑des‑Monts; died 15 January 1907 in Paris) was a French composer of the Romantic era. Prolific in opera and instrumental music — with many works for the oboe — she was among the most‑played composers at the Société Nationale de Musique in the 1870s and won the first Prix Rossini in 1881.</p><p>DoReDog has <strong>13</strong> Grandval pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Cl%C3%A9mence_de_Grandval\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Helena Munktell":"<p>Helena Mathilda Munktell (born 24 November 1852 in Grycksbo, Sweden; died 10 September 1919 in Stockholm) was a Swedish post‑Romantic composer of orchestral, vocal and operatic works. She became a member of the Royal Swedish Academy of Music and helped found the Swedish Society of Composers.</p><p>DoReDog has <strong>12</strong> Munktell pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Helena_Munktell\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Arthur Somervell":"<p>Sir Arthur Somervell (born 5 June 1863 in Windermere; died 2 May 1937 in London) was an English composer of the English Musical Renaissance, chiefly remembered for his song cycles — including settings of Tennyson's <em>Maud</em> and Housman's <em>A Shropshire Lad</em> — and as an influential reformer of music education.</p><p>DoReDog has <strong>9</strong> Somervell pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Arthur_Somervell\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Frank Bridge":"<p>Frank Bridge (born 26 February 1879 in Brighton; died 10 January 1941) was an English composer whose style evolved from late Romanticism toward modernism. He is known for the orchestral work <em>The Sea</em> and as the private teacher of Benjamin Britten, who paid tribute in his <em>Variations on a Theme of Frank Bridge</em>.</p><p>DoReDog has <strong>8</strong> Bridge pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Frank_Bridge\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Harry Thacker Burleigh":"<p>Harry Thacker Burleigh (born 2 December 1866 in Erie, Pennsylvania; died 12 September 1949 in Stamford, Connecticut) was an American composer and singer, a pioneering figure who arranged African‑American spirituals in a classical form and made them available to concert artists. He introduced Antonín Dvořák to Black American music.</p><p>DoReDog has <strong>8</strong> Burleigh pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Harry_Burleigh\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Chiquinha Gonzaga":"<p>Chiquinha Gonzaga (born Francisca Edwiges Neves Gonzaga; 17 October 1847 in Rio de Janeiro; died 28 February 1935 in Rio de Janeiro) was a Brazilian composer, pianist and conductor — the first woman conductor in Brazil and the first pianist of choro. She wrote the first Brazilian carnival march and composed roughly 2,000 works.</p><p>DoReDog has <strong>8</strong> Gonzaga pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Chiquinha_Gonzaga\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Alexander Mackenzie":"<p>Sir Alexander Campbell Mackenzie (born 22 August 1847 in Edinburgh; died 28 April 1935 in London) was a Scottish composer of the Romantic era, known for his oratorios, violin and piano pieces and works drawing on Scottish folk music. With Hubert Parry and Charles Villiers Stanford, he is regarded as one of the fathers of the British musical renaissance.</p><p>DoReDog has <strong>8</strong> Mackenzie pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Alexander_Mackenzie_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","Jean-Philippe Rameau":"<p>Jean-Philippe Rameau (born 25 September 1683 in Dijon; died 12 September 1764 in Paris) was a French composer of the late Baroque era who replaced Jean-Baptiste Lully as the leading composer of French opera. He was also a hugely influential theorist, whose 1722 <em>Treatise on Harmony</em> reshaped the understanding of music. His best-known works include the operas <em>Hippolyte et Aricie</em>, <em>Castor et Pollux</em> and <em>Les Indes galantes</em>. DoReDog has <strong>7</strong> Rameau pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Jean-Philippe_Rameau\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Richard Wagner":"<p>Wilhelm Richard Wagner (born 22 May 1813 in Leipzig; died 13 February 1883 in Venice) was a German composer of the Romantic era, best known for his operas. He revolutionised the form through his idea of the <em>Gesamtkunstwerk</em> (\"total work of art\"), uniting music, poetry, staging and drama. His major works include the cycle <em>Der Ring des Nibelungen</em>, <em>Tristan und Isolde</em>, <em>Die Meistersinger von Nürnberg</em> and <em>Parsifal</em>. DoReDog has <strong>6</strong> Wagner pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Richard_Wagner\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Henry Purcell":"<p>Henry Purcell (born around September 1659 in Westminster, London; died 21 November 1695 in London) was an English composer of the Baroque era, generally considered one of the greatest English composers. Extraordinarily prolific in his short life, he wrote more than 100 songs, the opera <em>Dido and Aeneas</em>, and semi-operas including <em>King Arthur</em> and <em>The Fairy-Queen</em>. DoReDog has <strong>5</strong> Purcell pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Henry_Purcell\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Gustav Mahler":"<p>Gustav Mahler (born 7 July 1860 in Kaliště, Bohemia; died 18 May 1911 in Vienna) was an Austro-Bohemian composer whose work bridged the 19th-century Romantic tradition and the modernism of the early 20th century. After his rediscovery following 1945 he became one of the most frequently performed composers. His best-known works include the Symphony No. 2, the Symphony No. 8 and <em>Das Lied von der Erde</em>. DoReDog has <strong>5</strong> Mahler pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Gustav_Mahler\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Frederick Delius":"<p>Frederick Delius (born 29 January 1862 in Bradford, England; died 10 June 1934 in Grez-sur-Loing, France) was an English composer of the late Romantic era, known for his individual orchestration and chromatic harmony. His best-known works include the orchestral pieces <em>Brigg Fair</em> and <em>On Hearing the First Cuckoo in Spring</em>, the opera <em>A Village Romeo and Juliet</em> and <em>A Mass of Life</em>. DoReDog has <strong>6</strong> Delius pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Frederick_Delius\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Hubert Parry":"<p>Sir Hubert Parry (born 27 February 1848 in Bournemouth; died 7 October 1918 in Rustington, West Sussex) was an English composer of the Romantic era and a central figure of the English Musical Renaissance. He is best known for his choral setting of Blake's \"Jerusalem\" and the coronation anthem \"I was glad,\" and was influential as a teacher and historian at the Royal College of Music. DoReDog has <strong>8</strong> Parry pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Hubert_Parry\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Dieterich Buxtehude":"<p>Dieterich Buxtehude (born around 1637; died 9 May 1707 in Lübeck) was a Danish-German composer of the middle Baroque era and a leading figure of the North German organ school (scholars dispute his exact birth year and country). His organ preludes form the core of his output, and his work profoundly influenced later composers including Bach and Handel. DoReDog has <strong>4</strong> Buxtehude pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Dieterich_Buxtehude\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Charles-Valentin Alkan":"<p>Charles-Valentin Alkan (born Charles-Valentin Morhange; 30 November 1813 in Paris; died 29 March 1888 in Paris) was a French composer and virtuoso pianist who, alongside his friends Chopin and Liszt, was among the leading pianists in Paris. His technically demanding piano works — including a Symphony and a Concerto for solo piano — were largely neglected until their revival from the 1960s onward. DoReDog has <strong>4</strong> Alkan pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Charles-Valentin_Alkan\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Emilie Mayer":"<p>Emilie Mayer (born 14 May 1812 in Friedland; died 10 April 1883 in Berlin) was a German composer of the Romantic era and one of the most prolific female composers of the 19th century. Sometimes called the \"female Beethoven,\" she wrote eight symphonies as well as chamber works, piano sonatas and overtures, earning recognition across Germany at a time of limited opportunity for women. DoReDog has <strong>6</strong> Mayer pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Emilie_Mayer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Luise Adolpha Le Beau":"<p>Luise Adolpha Le Beau (born 25 April 1850 in Rastatt; died 17 July 1927 in Baden-Baden) was a German composer, pianist, teacher and critic of the Romantic era. She won first prize for her Cello Sonata (Op. 17) in an international competition in 1882, and wrote orchestral, chamber and operatic works while overcoming the barriers faced by women musicians of her time. DoReDog has <strong>7</strong> Le Beau pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Luise_Adolpha_Le_Beau\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Maude Valérie White":"<p>Maude Valérie White (born 1855 in Dieppe, France; died 1937 in London) was a French-born English composer who became one of the most successful songwriters of the Victorian period, setting poetry in many languages. In 1879 she became the first woman to win the Mendelssohn Scholarship. DoReDog has <strong>6</strong> White pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Maude_Val%C3%A9rie_White\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Henry Rowley Bishop":"<p>Sir Henry Rowley Bishop (born 18 November 1787 in London; died 30 April 1856 in London) was an English composer of the late Classical and early Romantic eras, best remembered for the song \"Home! Sweet Home!\" In 1842 he became the first composer ever to be knighted, and he wrote or arranged around 120 dramatic works. DoReDog has <strong>7</strong> Bishop pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Henry_Bishop_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","Eduardo Di Capua":"<p>Eduardo Di Capua (born 12 May 1865 in Naples; died 3 October 1917 in Naples) was an Italian composer best known for writing the melody of the Neapolitan song \"'O sole mio,\" one of the most recorded songs in the world. He also composed \"O Marie.\" DoReDog has <strong>6</strong> Di Capua pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Eduardo_di_Capua\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Louis James Alfred Lefébure-Wély":"<p>Louis James Alfred Lefébure-Wély (born 13 November 1817 in Paris; died 31 December 1869 in Paris) was a French organist and composer of the Romantic era who played a major role in developing the French symphonic organ style. Closely associated with the organ builder Aristide Cavaillé-Coll, he inaugurated many of his new instruments and was celebrated as one of the finest organists of his day. DoReDog has <strong>6</strong> Lefébure-Wély pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Louis_James_Alfred_Lef%C3%A9bure-W%C3%A9ly\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Septimus Winner":"<p>Septimus Winner (born May 11, 1827 in Philadelphia, Pennsylvania; died November 22, 1905) was an American songwriter of the 19th century, known for popular ballads and songs. His most famous composition, \"Listen to the Mockingbird\" (1855), reportedly sold about 15 million copies in the United States, and he also wrote \"Der Deitcher's Dog\" (1864); he published under pseudonyms including Alice Hawthorne. DoReDog has 3 Winner pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Septimus_Winner\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Jakob Froberger":"<p>Johann Jakob Froberger (baptized 19 May 1616 in Stuttgart, Germany; died 6 or 7 May 1667 in Héricourt, France) was a German Baroque keyboard composer. He was influential in developing the musical form of the dance suite in his keyboard works, and also composed toccatas, ricercares, fantasias, canzonas, and capriccios. DoReDog has 3 Froberger pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Jakob_Froberger\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Friedrich Kuhlau":"<p>Friedrich Daniel Rudolf Kuhlau (born 11 September 1786 near Lüneburg in Lower Saxony, Germany; died 12 March 1832) was a German-born Danish composer of the late Classical and early Romantic periods and a central figure of the Danish Golden Age. Nicknamed \"the Beethoven of the flute\" for his many flute works, he is also remembered for his opera Elverhøj and his frequently performed piano sonatinas. DoReDog has 3 Kuhlau pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Friedrich_Kuhlau\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","August Kühnel":"<p>August Kühnel (born 3 August 1645; died ca. 1700) was a German Baroque composer and accomplished viola da gamba performer. He specialized in composing for the viola da gamba and published \"14 Sonate ò Partite ad una o due viole da gamba, con il basso continuo\" in 1698, the first printing of German trio sonatas in Germany. DoReDog has 3 Kühnel pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/August_K%C3%BChnel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","François Roberday":"<p>François Roberday (born 21 March 1624 in Paris; died 13 October 1680 in Auffargis, France) was a French Baroque organist and composer. He is best remembered for his Fugues et caprices (1660), a collection of four-part contrapuntal organ pieces, and is regarded as one of the last exponents of the French polyphonic tradition. DoReDog has 3 Roberday pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Fran%C3%A7ois_Roberday\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Matthias Weckmann":"<p>Matthias Weckmann (born c. 1616 in Niederdorla, Thuringia, Germany; died 24 February 1674 in Hamburg, Germany) was a German Baroque composer. He wrote chorale preludes and music for organ and harpsichord that mixed Italian and French influences, along with sonatas and sacred vocal works, and helped establish the Collegium Musicum in Hamburg. DoReDog has 3 Weckmann pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Matthias_Weckmann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Augusta Browne":"<p>Augusta Browne (full name Augusta Browne Garrett; born 1820 in Dublin, Ireland; died January 11, 1882 in New York City) was an American composer who immigrated from Ireland as a child and became one of the most prolific woman composers in America before 1870. She composed over 200 works for piano and voice plus numerous hymns, her best-known piece being \"Wake, Lady Mine\" (1845). DoReDog has 3 Browne pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Augusta_Browne\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Emmanuel Chabrier":"<p>Alexis-Emmanuel Chabrier (born 18 January 1841 in Ambert, Puy-de-Dôme, France; died 13 September 1894 in Paris) was a French Romantic composer. He is best remembered for his orchestral works España and Joyeuse marche, and also composed operas such as L'étoile and Le roi malgré lui, along with piano works and songs. DoReDog has 3 Chabrier pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Emmanuel_Chabrier\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Frederic Hymen Cowen":"<p>Sir Frederic Hymen Cowen (born 29 January 1852 in Kingston, Jamaica; died 6 October 1935) was an English composer, conductor, and pianist of the Romantic era. His most celebrated work, the Symphony No. 3 in C minor (Scandinavian), first performed in 1880, became one of the most popular symphonic works in the repertoire, and he composed over 300 songs. DoReDog has 3 Cowen pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Frederic_Hymen_Cowen\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ellen Dickson":"<p>Ellen Dickson (born 1819 in Woolwich, England; died 4 July 1878 in Lyndhurst, England), who composed under the pen name \"Dolores,\" was an English composer of the Victorian era. She began making her reputation in the late 1850s composing drawing-room ballads, and is particularly known for \"The Bridge\" (1857), a setting of a Henry Wadsworth Longfellow text. DoReDog has 3 Dickson pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ellen_Dickson\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Edward German":"<p>Sir Edward German (born German Edward Jones on 17 February 1862 in Whitchurch, Shropshire, England; died 11 November 1936 in Maida Vale, London) was an English composer of the Victorian and Edwardian periods. Remembered as a successor to Arthur Sullivan in English comic opera, he is best known for Merrie England (1902) and Tom Jones (1907), as well as his Welsh Rhapsody (1904). DoReDog has 3 German pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Edward_German\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Poldowski":"<p>Poldowski was the professional pseudonym of Régine Wieniawski (also known as Irène Wieniawska and Lady Dean Paul; born 16 May 1879 in Ixelles, Brussels, Belgium; died 28 January 1932 in London, England), a Belgian-born British composer of the late Romantic to early Modern period and daughter of violinist Henryk Wieniawski. A gifted composer of songs strongly influenced by Debussy, she is noted for setting 22 French poems by Paul Verlaine, including \"Mandoline\" and \"L'heure exquise.\" DoReDog has 3 Poldowski pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Poldowski\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Loïsa Puget":"<p>Louise Françoise \"Loïsa\" Puget (born 11 February 1810 in Paris, France; died 24 October 1889 in Pau, France) was a French composer of the Romantic 19th century. Prolific between 1830 and 1845, she composed the music for over 300 songs, her most successful being \"À la grâce de Dieu.\" DoReDog has 3 Puget pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Lo%C3%AFsa_Puget\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giacomo Puccini":"<p>Giacomo Antonio Domenico Michele Secondo Maria Puccini (born 22 December 1858 in Lucca, Grand Duchy of Tuscany; died 29 November 1924 in Brussels, Belgium) was an Italian composer of the late Romantic period, regarded as the greatest and most successful proponent of Italian opera after Verdi. A leading exponent of the verismo style, he is known for operas including La bohème (1896), Tosca (1900), Madama Butterfly (1904), and Turandot. DoReDog has 2 Puccini pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giacomo_Puccini\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Franz Gruber":"<p>Franz Xaver Gruber (born 25 November 1787 in Hochburg-Ach, Upper Austria; died 7 June 1863 in Hallein, Salzburg) was an Austrian primary school teacher, church organist, and composer of the 19th century. He is best known for composing the music to \"Stille Nacht\" (\"Silent Night\") on Christmas Eve 1818 in collaboration with lyricist Joseph Mohr. DoReDog has 2 Gruber pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Franz_Xaver_Gruber\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","J. K. F. Fischer":"<p>Johann Caspar Ferdinand Fischer (also spelled Johann Kaspar Ferdinand Fischer; born c. 1656 in Schönfeld, Bohemia; died 27 August 1746 in Rastatt) was a German Baroque composer credited with bringing many French elements into German music. He is best known for <em>Ariadne musica</em> (1702), a significant precursor to Bach's <em>The Well-Tempered Clavier</em>, as well as <em>Musikalischer Parnassus</em> and the orchestral suites <em>Le journal du printemps</em> (1695). DoReDog has 3 Fischer pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Caspar_Ferdinand_Fischer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Francesco Florimo":"<p>Francesco Florimo (born 12 October 1800 in San Giorgio Morgeto, Calabria; died 18 December 1888 in Naples) was an Italian musician, historian, and librarian of the 19th century. In 1826 he became archivist-librarian of the Naples Conservatory, and he is known for his multi-volume history <em>La scuola musicale di Napoli e i suoi conservatori</em> (1880–82) and for documenting his lifelong friend Vincenzo Bellini. DoReDog has 3 Florimo pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Francesco_Florimo\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Stephen Ralph Glover":"<p>Stephen Glover (born 1812 or 1813 in London; died 7 December 1870) was an English composer of the 19th century. He became a popular composer of songs, ballads, and duets, producing some fourteen or fifteen hundred compositions, with notable works including <em>What are the Wild Waves Saying</em> (1850) and <em>The Monks of Old</em> (1842). DoReDog has 3 Glover pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Stephen_Glover_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","Christoph Willibald Gluck":"<p>Christoph Willibald (Ritter von) Gluck (born 2 July 1714 in Erasbach, Upper Palatinate; died 15 November 1787 in Vienna) was a composer of Italian and French opera in the early Classical period. He brought about a practical reform of opera, prioritising drama over vocal display, and is best known for <em>Orfeo ed Euridice</em> (1762), <em>Alceste</em> (1767) and <em>Iphigénie en Tauride</em> (1779). DoReDog has 3 Gluck pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Christoph_Willibald_Gluck\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Charles Gounod":"<p>Charles-François Gounod (born 17 June 1818 in Paris; died 18 October 1893 in Saint-Cloud, near Paris) was a French composer of the Romantic era. He is best known for his operas — in particular <em>Faust</em> (1859) and <em>Roméo et Juliette</em> (1867) — as well as for religious works including his <em>Ave Maria</em>, an elaboration of a Bach prelude. DoReDog has 3 Gounod pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Charles_Gounod\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Hans Leo Hassler":"<p>Hans Leo Hassler (baptised 26 October 1564 in Nuremberg; died 8 June 1612 in Frankfurt) was a German composer of the late Renaissance and early Baroque, one of the first to bring the innovations of the Venetian style across the Alps. His works include the <em>lieder</em> collection <em>Lustgarten Neuer Teutscher Gesäng</em> (1601) and the <em>Cantiones sacrae</em> (1591). DoReDog has 3 Hassler pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Hans_Leo_Hassler\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Henri Herz":"<p>Heinrich \"Henri\" Herz (born 6 January 1803 in Vienna; died 5 January 1888) was a virtuoso pianist and composer, Austrian by birth and French by nationality and domicile, active in the 19th century. He was a professor at the Paris Conservatoire for over thirty years and a piano manufacturer, and his output includes eight piano concertos along with sonatas, rondos, nocturnes and variations. DoReDog has 3 Herz pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Henri_Herz\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Adolf Jensen":"<p>Adolf Jensen (born 12 January 1837 in Königsberg; died 23 January 1879 in Baden-Baden) was a German pianist, composer and music teacher of the 19th-century Romantic period. He composed roughly 160 art songs and choral pieces, along with piano works such as the <em>Sonata in F-sharp minor</em> (Op. 25), the 25 Études (Op. 32) and <em>Erotikon</em> (Op. 44). DoReDog has 3 Jensen pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Adolf_Jensen\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Heinrich Lichner":"<p>Heinrich Lichner (born 6 March 1829 in Harpersdorf, Silesia; died 7 January 1898 in Breslau) was a German composer of the 19th-century Romantic period who also worked as an organist and choral festival director. He is best known today for his teaching pieces — simple piano works written for students, including his sonatinas (Opp. 4, 49 and 66). DoReDog has 3 Lichner pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Heinrich_Lichner\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Jean-Baptiste Lully":"<p>Jean-Baptiste Lully, born Giovanni Battista Lulli (28 or 29 November 1632 in Florence; died 22 March 1687 in Paris), was an Italian-French composer considered a master of the French Baroque style, having become a French subject in 1661. Best known for his operas, he created French-style opera as a genre and is credited with inventing the French overture; his collaborations with Molière include <em>Le Bourgeois gentilhomme</em>. DoReDog has 3 Lully pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Jean-Baptiste_Lully\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Claudio Merulo":"<p>Claudio Merulo, born Claudio Merlotti (8 April 1533 in Correggio; died 4 May 1604 in Parma), was an Italian composer, publisher and organist of the late Renaissance. He was most famous for his innovative keyboard music and his ensemble music in the Venetian polychoral style; his toccatas were the first to contrast sections of contrapuntal writing with passagework. DoReDog has 3 Merulo pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Claudio_Merulo\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giovanni Pierluigi da Palestrina":"<p>Giovanni Pierluigi da Palestrina (born between 3 February 1525 and 2 February 1526 in Palestrina; died 2 February 1594 in Rome) was an Italian composer of the late Renaissance and the central representative of the Roman School. His vast output includes over 105 masses and more than 300 motets — most notably the <em>Missa Papae Marcelli</em> — and he lent his name to the \"Palestrina style\" of counterpoint. DoReDog has 3 Palestrina pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giovanni_Pierluigi_da_Palestrina\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ferdinand Praeger":"<p>Ferdinand Christian Wilhelm Praeger (born 22 January 1815 in Leipzig; died 2 September 1891 in London) was a German composer, pianist, music teacher and writer of the 19th century. He is best known for his controversial biography of Richard Wagner, <em>Wagner As I Knew Him</em> (published 1892), and his compositions include thirty-six piano sonatas and twenty-five string quartets. DoReDog has 3 Praeger pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ferdinand_Praeger\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Max Reger":"<p>Max Reger (born Johann Baptist Joseph Maximilian Reger; 19 March 1873 in Brand, Bavaria; died 11 May 1916 in Leipzig) was a German composer, pianist, organist and teacher of the late Romantic era. He produced an enormous output in just over 25 years, nearly always in abstract forms, with celebrated works including the <em>Variations and Fugue on a Theme by Mozart</em> (1914) and <em>Der 100. Psalm</em> (1909). DoReDog has 3 Reger pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Max_Reger\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Walter Parratt":"<p>Sir Walter Parratt (born 10 February 1841 in Huddersfield, Yorkshire; died 27 March 1924 in Windsor) was an English organist and composer of the late Romantic era. He served as Master of the Queen's Music and later Master of the King's Music from 1893 to 1924, was one of the foremost organ teachers of his day, and held organist posts at Magdalen College, Oxford and St George's Chapel, Windsor Castle. DoReDog has 11 Parratt pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Walter_Parratt\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Emilie Zumsteeg":"<p>Emilie Zumsteeg (born 9 December 1796 in Stuttgart; died 1 August 1857 in Stuttgart) was a German choral conductor, singer, composer and pianist of the Romantic era. She is best known for her roughly sixty songs, and in 1830 she founded the first women's choir in Württemberg; her output also included an overture, piano works and sacred choral music. DoReDog has 10 Zumsteeg pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Emilie_Zumsteeg\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Luise Greger":"<p>Luise Greger (born 27 December 1862 in Greifswald; died 25 January 1944 in Merxhausen, Hesse) was a German composer and pianist active around the turn of the 20th century. While she was in Berlin in the 1890s, Richard Strauss proclaimed her a composer; one of her notable works was a musical Christmas fairytale, \"Goose Girl,\" performed to acclaim in 1933–34. DoReDog has 9 Greger pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Luise_Greger\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Guy d’ Hardelot":"<p>Guy d'Hardelot was the pen name of Helen Rhodes (née Helen Guy; born August 1858 at the Château d'Hardelot near Boulogne-sur-Mer, France; died 7 January 1936). A French composer, pianist and teacher of the late 19th and early 20th centuries, she was among the most popular women composers of her day, best known for her song \"Because,\" along with \"Sans Toi\" and \"I Know a Lovely Garden.\" DoReDog has 9 d'Hardelot pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Guy_d%27Hardelot\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Walford Davies":"<p>Sir Henry Walford Davies (born 6 September 1869 in Oswestry, Shropshire; died 11 March 1941 in Wrington, Somerset) was an English composer, organist and educator. He served as Master of the King's Music from 1934 to 1941 and became well known as a BBC music broadcaster; his celebrated works include the \"Royal Air Force March Past,\" \"God Be in My Head\" and \"Solemn Melody.\" DoReDog has 7 Davies pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Walford_Davies\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Laura Netzel":"<p>Laura Netzel (née Pistolekors; 1 March 1839 in Rantasalmi, Finland – 10 February 1927 in Stockholm) was a Finnish-born Swedish composer, pianist and conductor of the Romantic era. She presided over the women's musical arts at the 1893 Chicago World's Fair and is counted among the prominent Swedish women composers of the 19th century; her most ambitious work was a <em>Stabat Mater</em>. DoReDog has 7 Netzel pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Laura_Netzel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Jean Henri Ravina":"<p>Jean-Henri Ravina (born 20 May 1818; died 30 September 1906) was a French virtuoso pianist, composer and teacher of the 19th-century Romantic era. He published piano works including études, concertos, rondos, divertimentos, variations and fantasies, transcribed Beethoven's symphonies for piano four-hands, and was made a Chevalier of the Legion of Honour in 1861. DoReDog has 6 Ravina pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Jean-Henri_Ravina\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ann Mounsey Bartholomew":"<p>Ann Sheppard Mounsey, known after marriage as Ann Mounsey Bartholomew (born 17 April 1811 in Soho, London; died 24 June 1891 in Shoreditch, London), was a British church organist and composer of the 19th century. Her extensive catalogue spans oratorios, cantatas, part songs, around 120 solo songs, and organ and piano pieces, and she served nearly 50 years as organist at St Vedast's Church, Foster Lane. DoReDog has 6 Mounsey pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ann_Mounsey\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Joseph Ascher":"<p>Joseph Simon Ascher (born 3 June 1829 in Groningen, Netherlands; died 20 June 1869 in London) was a Dutch pianist and composer of the Romantic era. He was appointed court pianist to Empress Eugénie of France in 1849 and composed roughly 170 works, chiefly for piano, including \"Les Hirondelles,\" \"Le Papillon\" and \"Alice, Where Art Thou?\" DoReDog has 5 Ascher pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Joseph_Ascher\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Granville Bantock":"<p>Sir Granville Ransome Bantock (born 7 August 1868 in London; died 16 October 1946 in London) was a British composer of the late Romantic era known for large orchestral and choral works. He was Peyton Professor of Music at the University of Birmingham from 1908 to 1934, succeeding Edward Elgar; his notable compositions include the choral epic \"Omar Khayyám,\" the \"Hebridean Symphony\" and \"Pagan Symphony.\" DoReDog has 5 Bantock pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Granville_Bantock\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Charlotte Alington - aka Claribel Barnard":"<p>Charlotte Alington Barnard (born Charlotte Alington Pye; 23 December 1830 in Louth, Lincolnshire; died 30 January 1869 in Dover), who wrote under the pen name \"Claribel,\" was an English poet and composer of ballads and hymns of the Victorian era. She wrote over 100 songs as well as two volumes of verse and was the most commercially successful ballad composer managed by her publishers, Boosey's; her best-known songs include \"Come Back to Erin.\" DoReDog has 5 Barnard pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Charlotte_Alington_Barnard\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ivor Gurney":"<p>Ivor Bertie Gurney (born 28 August 1890 in Gloucester; died 26 December 1937 in Dartford) was an English composer and poet of the early 20th century, regarded as one of the great World War I poets, who wrote over 300 songs and hundreds of poems. His works include the poetry collections <em>Severn and Somme</em> (1917) and <em>War's Embers</em> (1919) and the song cycles <em>Ludlow and Teme</em> and <em>The Western Playland</em>. DoReDog has 5 Gurney pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ivor_Gurney\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Carrie Jacobs-Bond":"<p>Carrie Jacobs-Bond (born Carrie Minetta Jacobs; 11 August 1862 in Janesville, Wisconsin; died 28 December 1946 in Hollywood, California) was an American composer active from the 1890s through the early 1940s. She composed some 175 pieces of popular music, was best remembered for the parlour song \"I Love You Truly,\" and became the first woman to sell one million copies of a song. DoReDog has 5 Jacobs-Bond pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Carrie_Jacobs-Bond\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Amelia Lehmann":"<p>Amelia Lehmann (née Chambers; born 3 February 1838; died 1 April 1903) was a British composer and arranger of art songs and popular ballads, many published under the pseudonym \"A. L.\" A gifted singer, she was the first singing teacher of her daughter, the composer Liza Lehmann, and several of her works were performed at the Henry Wood Promenade Concerts. DoReDog has 5 Lehmann pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Amelia_Lehmann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Pasquale Mario Costa":"<p>Pasquale Mario Costa (born 24 July 1858 in Taranto; died 27 September 1933 in Monte Carlo) was a prolific Italian composer primarily known for his art songs, Neapolitan songs and operettas. Active in the revival of the Neapolitan musical tradition after a period working in London, he later concentrated on operettas, pantomimes and ballets. DoReDog has 4 Costa pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Mario_Pasquale_Costa\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Guillaume Louis Cottrau":"<p>Guillaume Louis Cottrau (born 10 August 1797 in Paris; died 31 October 1847 in Naples) was a French-Italian composer and music publisher. He is known for publishing <em>Passatempi musicali</em>, a collection of Neapolitan songs (including some of his own) that helped the genre spread abroad; one of his themes was taken up by Franz Liszt for his \"Tarentelle napolitaine.\" DoReDog has 4 Cottrau pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Guillaume_Louis_Cottrau\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Adriano Banchieri":"<p>Adriano Banchieri (born 3 September 1568 in Bologna; died 1634 in Bologna) was an Italian composer, music theorist, organist and poet of the late Renaissance and early Baroque. A Benedictine monk, he was one of the developers of the madrigal comedy and founded the Accademia dei Floridi in Bologna. DoReDog has 4 Banchieri pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Adriano_Banchieri\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Heinrich Scheidemann":"<p>Heinrich Scheidemann (born circa 1595 in Wöhrden, Holstein; died 1663 in Hamburg) was a German Baroque composer and organist. A pupil of Jan Pieterszoon Sweelinck, he was the best-known organ composer in north Germany in the early-to-mid 17th century, remembered especially for his Lutheran chorale settings and chorale fantasias. DoReDog has 4 Scheidemann pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Heinrich_Scheidemann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Pauline Duchambge":"<p>Pauline Duchambge (née de Montet; born 1778 in Martinique; died 23 April 1858) was a French pianist, singer and composer. She is known for composing over three hundred <em>romances</em> — a very popular genre in the 19th century — and for her lifelong collaboration with the poet Marceline Desbordes-Valmore. DoReDog has 4 Duchambge pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Pauline_Duchambge\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Evelyn Faltis":"<p>Evelyn Faltis (born 20 February 1887 in Trutnov, Bohemia; died 13 May 1937 in Vienna) was a Czech composer of the 20th century and the first female coach at Bayreuth. She composed for orchestra, chamber ensemble and chorus, with works including piano trios, concertos, symphonic poems and string quartets. DoReDog has 4 Faltis pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Evelyn_Faltis\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Virginia Gabriel":"<p>Mary Anne Virginia Gabriel (born 7 February 1825 in Banstead, Surrey; died 7 August 1877) was an English singer and composer of the Romantic 19th century. She was known for her cantatas and operas as well as popular ballads, with works including the cantatas <em>Evangeline</em>, <em>Graziella</em> and <em>Dreamland</em>. DoReDog has 4 Gabriel pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Virginia_Gabriel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Amy Elsie Horrocks":"<p>Amy Elsie Horrocks (born 23 February 1867 in Rio Grande do Sul, Brazil; died 4 December 1919 in Paris) was an English music educator, composer and pianist, born to English parents. Working in the late 19th and early 20th centuries, she is known for songs such as \"The Bird and the Rose,\" and several of her works were performed at the Proms. DoReDog has 4 Horrocks pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Amy_Horrocks\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Richard Strauss":"<p>Richard Georg Strauss (born 11 June 1864 in Munich; died 8 September 1949 in Garmisch-Partenkirchen) was a German composer of the late Romantic and early Modern era. He is celebrated for his tone poems, including <em>Also sprach Zarathustra</em> and <em>Don Juan</em>, and for operas such as <em>Der Rosenkavalier</em>, generally considered his finest achievement. DoReDog has 4 Strauss pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Richard_Strauss\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giuseppe Verdi":"<p>Giuseppe Fortunino Francesco Verdi (born 9 or 10 October 1813 in Le Roncole; died 27 January 1901 in Milan) was an Italian composer who came to dominate the 19th-century Italian opera scene. His celebrated middle-period operas include <em>Rigoletto</em> and <em>La traviata</em>, and his later <em>Aida</em> was commissioned in connection with the opening of the Suez Canal. DoReDog has 3 Verdi pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giuseppe_Verdi\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Vincenzo Di Chiara":"<p>Vincenzo Di Chiara (born 1864 in Naples; died 1937 in Naples) was an Italian baritone and composer of popular art songs. He is chiefly remembered for \"La spagnola,\" a worldwide hit later recorded by Rosa Ponselle. DoReDog has 3 Di Chiara pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Vincenzo_Di_Chiara\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Strauss II":"<p>Johann Strauss II (born 25 October 1825 near Vienna; died 3 June 1899 in Vienna) was an Austrian composer of the Romantic era. Known as \"The Waltz King,\" he did much to popularise the waltz and composed over 500 waltzes, polkas and marches, as well as operettas such as <em>Die Fledermaus</em>. He is best remembered for \"The Blue Danube.\" DoReDog has 2 Strauss pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Strauss_II\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Camille Saint-Saëns":"<p>Charles-Camille Saint-Saëns (born 9 October 1835 in Paris; died 16 December 1921 in Algiers) was a French composer of the Romantic era. A prodigy who made his concert debut at ten, he became one of the most prolific French composers; his notable works include <em>Danse macabre</em>, the opera <em>Samson and Delilah</em>, the \"Organ\" Symphony and <em>The Carnival of the Animals</em>. DoReDog has 2 Saint-Saëns pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Camille_Saint-Sa%C3%ABns\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","C. P. E. Bach":"<p>Carl Philipp Emanuel Bach (born 8 March 1714 in Weimar; died 14 December 1788 in Hamburg), a son of J. S. Bach, was a German composer of the Baroque-to-Classical transition and a principal representative of the <em>empfindsamer Stil</em> (\"sensitive style\"). His <em>Essay on the True Art of Playing Keyboard Instruments</em> was studied by Haydn, Mozart and Beethoven, and his best-known piece is the <em>Solfeggietto</em>. DoReDog has 2 Bach pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Carl_Philipp_Emanuel_Bach\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","André Campra":"<p>André Campra (baptised 4 December 1660 in Aix-en-Provence; died 29 June 1744 in Versailles) was a French composer of the Baroque era — the leading French opera composer in the period between Lully and Rameau, offering a lighter alternative to the grave <em>tragédie en musique</em>. His notable works include the opéra-ballet <em>L'Europe galante</em> (1697) and numerous grands motets. DoReDog has 2 Campra pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Andr%C3%A9_Campra\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giovanni Carlo Maria Clari":"<p>Giovanni Carlo Maria Clari (born 27 September 1677 in Pisa; died 16 May 1754) was an Italian composer of the Baroque era who served as <em>maestro di cappella</em> at Pistoia, Bologna and Pisa. He is best known for his vocal duets and trios with basso continuo, published between 1740 and 1747, which combined graceful melody with contrapuntal skill. DoReDog has 2 Clari pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giovanni_Carlo_Maria_Clari\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","François Couperin":"<p>François Couperin (born 10 November 1668 in Paris; died 11 September 1733) was a French Baroque composer, organist and harpsichordist known as \"Couperin le Grand\" (\"Couperin the Great\") to distinguish him from his musical family. He is renowned for his four volumes of <em>Pièces de clavecin</em> and his treatise <em>L'art de toucher le clavecin</em>. DoReDog has 2 Couperin pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Fran%C3%A7ois_Couperin\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Richard Eilenberg":"<p>Richard Eilenberg (born 13 January 1848 in Merseburg; died 5 December 1927 in Berlin) was a German composer of the Romantic period who completed some 350 compositions, specialising in marches, orchestral dances and salon pieces. His best-known works include \"The Petersburg Sleigh Ride\" (Op. 52) and \"The Mill in the Black Forest\" (Op. 57). DoReDog has 2 Eilenberg pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Richard_Eilenberg\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","César Franck":"<p>César Franck (born 10 December 1822 in Liège; died 8 November 1890 in Paris) was a Belgian-born composer, organist and teacher of the Romantic era who became a French citizen in 1872. Regarded as one of the greatest composers of organ music after Bach, his notable works include the Symphony in D minor, the Violin Sonata in A major and <em>Panis angelicus</em>. DoReDog has 2 Franck pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/C%C3%A9sar_Franck\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Andrea Gabrieli":"<p>Andrea Gabrieli (born 1532/1533 in Venice; died 30 August 1585 in Venice) was an Italian composer and organist of the Renaissance — the first internationally renowned member of the Venetian School. Organist at St Mark's Basilica from 1566, he helped develop the polychoral style and taught his nephew Giovanni Gabrieli. DoReDog has 2 Gabrieli pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Andrea_Gabrieli\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Niels Gade":"<p>Niels Wilhelm Gade (born 22 February 1817 in Copenhagen; died 21 December 1890 in Copenhagen) was a Danish composer, conductor and teacher of the Romantic period and the Danish Golden Age. Regarded as the leading Danish musician of his day, he wrote eight symphonies and the concert overture <em>Efterklange af Ossian</em>, and taught composers including Grieg and Nielsen. DoReDog has 2 Gade pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Niels_Gade\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Eugène Gigout":"<p>Eugène Gigout (born 23 March 1844 in Nancy; died 9 December 1925 in Paris) was a French organist and composer who wrote mostly for his own instrument. He was organist of Saint-Augustin in Paris for 62 years and a celebrated teacher and improviser; his best-known work is the <em>Toccata in B minor</em> from his <em>10 pièces pour orgue</em> (1890). DoReDog has 2 Gigout pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Eug%C3%A8ne_Gigout\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Louis Moreau Gottschalk":"<p>Louis Moreau Gottschalk (born 8 May 1829 in New Orleans; died 18 December 1869 in Rio de Janeiro) was an American pianist and composer of the Romantic period. A touring virtuoso, his piano works drew on his Louisiana Creole heritage and are considered early examples of Creole idioms in classical music; they include <em>Bamboula</em>, <em>La Savane</em> and <em>Souvenir de Porto Rico</em>. DoReDog has 2 Gottschalk pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Louis_Moreau_Gottschalk\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Nicolaus Hanff":"<p>Johann Nikolaus Hanff (born 25 September 1663 in Wechmar, Thuringia; died 25 December 1711) was a North German Baroque organist and composer. In 1696 he became organist and conductor to the Bishop of Lübeck, and he taught harpsichord and composition to Johann Mattheson in Hamburg. DoReDog has 2 Hanff pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Nikolaus_Hanff\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Anthony Philip Heinrich":"<p>Anthony Philip Heinrich (born 11 February 1781 in Schönbüchel, Bohemia; died 3 May 1861 in New York City) was a Bohemian-born American composer, recognised as the first \"full-time\" American composer and the most prominent before the Civil War. Dubbed the \"Beethoven of America,\" he chaired the founding meeting of the New York Philharmonic Society in 1842. DoReDog has 2 Heinrich pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Anthony_Philip_Heinrich\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Stephen Heller":"<p>Stephen Heller (born 15 May 1813 in Pest, Hungary; died 14 January 1888) was a Hungarian pianist, teacher and composer of the Romantic period. A prolific composer for the piano, his studies remain popular with music teachers and students to this day. DoReDog has 2 Heller pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Stephen_Heller\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Adolf von Henselt":"<p>Adolf von Henselt (born 9 May 1814 in Schwabach, Bavaria; died 10 October 1889 at Warmbrunn) was a German composer and virtuoso pianist of the Romantic period who served as court pianist in Saint Petersburg. He is known for his Piano Concerto in F minor (Op. 16) and his Twelve Characteristic Studies (Op. 2). DoReDog has 2 Henselt pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Adolf_von_Henselt\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Salomon Jadassohn":"<p>Salomon Jadassohn (born 13 August 1831 in Breslau; died 1 February 1902 in Leipzig) was a German pianist, composer and teacher at the Leipzig Conservatory. A renowned teacher whose students included Ferruccio Busoni and Frederick Delius, he composed four symphonies, two piano concertos, chamber music and organ works. DoReDog has 2 Jadassohn pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Salomon_Jadassohn\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Friedrich Wilhelm Kalkbrenner":"<p>Friedrich Wilhelm Kalkbrenner (born 7 November 1785; died 10 June 1849 in Enghien-les-Bains) was a German-born pianist, composer, teacher and piano manufacturer of the Romantic era who settled in Paris. He composed more than 200 piano works plus concertos, wrote a famous piano method (1831), and Chopin dedicated his first piano concerto to him. DoReDog has 2 Kalkbrenner pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Friedrich_Kalkbrenner\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Ludwig Krebs":"<p>Johann Ludwig Krebs (baptised 12 October 1713 in Buttelstedt; died 1 January 1780 in Altenburg) was a German Baroque composer of organ, harpsichord and orchestral works. A pupil of Johann Sebastian Bach on the organ — and held by Bach in high regard — he became court organist of Saxe-Gotha-Altenburg in 1755. DoReDog has 2 Krebs pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Ludwig_Krebs\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Michael Praetorius":"<p>Michael Praetorius (born probably 28 September 1571 in Creuzburg, Thuringia; died 15 February 1621 in Wolfenbüttel) was a German composer, organist and music theorist of the late Renaissance and early Baroque. He is known for <em>Terpsichore</em> (1612), a compendium of more than 300 instrumental dances, and for his treatise <em>Syntagma Musicum</em>. DoReDog has 2 Praetorius pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Michael_Praetorius\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Geo. F. Root":"<p>George Frederick Root (born 30 August 1820 in Sheffield, Massachusetts; died 6 August 1895 at Bailey Island, Maine) was an American composer of the 19th century who gained fame during the Civil War as a songwriter, with songs including \"The Battle Cry of Freedom\" and \"Tramp! Tramp! Tramp!\" He is regarded as the first American to compose a secular cantata. DoReDog has 2 Root pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/George_Frederick_Root\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Anton Rubinstein":"<p>Anton Rubinstein (born 28 November 1829 in Vikhvatinets, Podolia; died 20 November 1894 in Peterhof) was a Russian pianist, composer and conductor of the Romantic period. He founded the Saint Petersburg Conservatory, ranked among the great 19th-century keyboard virtuosos, and composed twenty operas (notably <em>The Demon</em>), five piano concertos and six symphonies. DoReDog has 2 Rubinstein pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Anton_Rubinstein\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Hermann Schein":"<p>Johann Hermann Schein (born 20 January 1586 in Grünhain; died 19 November 1630 in Leipzig) was a German composer of the early Baroque and Thomaskantor at Leipzig from 1615. He was one of the first to bring early Italian stylistic innovations into German music; his best-known collection is the <em>Banchetto musicale</em> (1617). DoReDog has 2 Schein pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Hermann_Schein\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Sophie Gail":"<p>Edmée Sophie Gail (née Garre; born 28 August 1775 in Paris; died 24 July 1819 in Paris) was a French singer and composer, famous for writing <em>romances</em> and <em>opéra comique</em>. Her popular works include <em>Les deux jaloux</em> (1813) and <em>La Sérénade</em> (1818), which were much admired during her lifetime. DoReDog has 2 Gail pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Sophie_Gail\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Jane Mary Guest":"<p>Jane Mary Guest (also Jenny Guest, later Jane Mary Miles; born c. 1762, probably in Bath; died 20 March 1846 in Blackheath, London) was an English pianist and composer. A pupil of Johann Christian Bach working in the <em>galante</em> style, she served as piano teacher to Princess Amelia and Princess Charlotte of Wales; her works include <em>Six Sonatas</em>, Op. 1. DoReDog has 2 Guest pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Jane_Mary_Guest\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Maria Lindsay":"<p>Maria Lindsay (married name Bliss; born 15 May 1827 in Wimbledon; died 3 April 1898 in Betteshanger, Kent) was an English composer and songwriter — one of the first women to achieve commercial success as an English songwriter in the 19th century. Her sacred and popular songs, often set to contemporary poetry, include <em>Excelsior</em> (1854) and <em>Home They Brought Her Warrior Dead</em> (1858). DoReDog has 2 Lindsay pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Maria_Lindsay\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Florence Ashton Marshall":"<p>Florence Ashton Marshall (née Thomas; born 30 March 1843 in Rome; died 5 March 1922) was an English composer, conductor and author. She studied at the Royal Academy of Music and conducted the South Hampstead Orchestra for over 30 years, composing works such as the fairy operetta <em>Prince Sprite</em> (1897) and a Symphony in B minor. DoReDog has 2 Marshall pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Florence_Ashton_Marshall\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Elizabeth Philp":"<p>Elizabeth Philp (born 1827 in Falmouth, Cornwall; died 26 November 1885 in London) was an English singer, music educator and composer. She studied with Ferdinand Hiller in Cologne and focused on English vocal music, publishing the collection <em>How to Sing an English Ballad</em> and setting texts by poets such as Elizabeth Barrett Browning. DoReDog has 2 Philp pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Elizabeth_Philp\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Clara Schumann":"<p>Clara Schumann (née Wieck; born 13 September 1819 in Leipzig; died 20 May 1896 in Frankfurt) was a German virtuoso pianist, composer and teacher of the Romantic period, and the wife of Robert Schumann. Over a 61-year concert career she also composed solo piano pieces, a piano concerto, chamber music and songs, including her Piano Concerto in A minor and Three Romances for Violin and Piano. DoReDog has 2 Schumann pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Clara_Schumann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Arthur Sullivan":"<p>Sir Arthur Seymour Sullivan (born 13 May 1842 in Lambeth, London; died 22 November 1900 in Westminster) was an English composer best known for his fourteen comic-opera collaborations with the dramatist W. S. Gilbert, including <em>H.M.S. Pinafore</em>, <em>The Pirates of Penzance</em> and <em>The Mikado</em>. He also wrote the hymn \"Onward, Christian Soldiers.\" DoReDog has 2 Sullivan pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Arthur_Sullivan\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Alice Tegnér":"<p>Alice Tegnér (née Sandström; born 12 March 1864 in Karlshamn; died 26 May 1943 in Djursholm) was a Swedish composer — the foremost composer of Swedish children's songs of her era. Her most famous composition is <em>Mors lilla Olle</em> (1895). DoReDog has 2 Tegnér pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Alice_Tegn%C3%A9r\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Samuel A. Ward":"<p>Samuel Augustus Ward (born 28 December 1848 in Newark, New Jersey; died 28 September 1903 in Newark) was an American organist and composer. He composed the tune \"Materna\" in 1882, which was later paired with Katharine Lee Bates' poem to create \"America the Beautiful.\" DoReDog has 1 Ward piece in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Samuel_A._Ward\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Niccolò Paganini":"<p>Niccolò Paganini (born 27 October 1782 in Genoa; died 27 May 1840 in Nice) was an Italian violin virtuoso and composer of the Romantic period, celebrated for his 24 Caprices for Solo Violin (Op. 1). The last of these, Caprice No. 24 in A minor, has served as the basis for works by many later composers, including Brahms and Rachmaninoff. DoReDog has 1 Paganini piece in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Niccol%C3%B2_Paganini\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Christian Petzold":"<p>Christian Petzold (born 15 March 1677 in Weißig, near Königstein; died 25 May 1733) was a German Baroque composer and organist. He is best known as the actual composer of the famous Minuet in G major (BWV Anh. 114), long attributed to J. S. Bach until his authorship was established in the 1970s; it appears in the 1725 <em>Notebook for Anna Magdalena Bach</em>. DoReDog has 1 Petzold piece in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Christian_Petzold_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","Edward MacDowell":"<p>Edward MacDowell (born 18 December 1860 in New York City; died 23 January 1908 in New York City) was an American composer of the late Romantic period. He is best known for his second piano concerto and his piano suites <em>Woodland Sketches</em>, <em>Sea Pieces</em> and <em>New England Idylls</em>; <em>Woodland Sketches</em> contains his most popular short piece, \"To a Wild Rose.\" DoReDog has 1 MacDowell piece in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Edward_MacDowell\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Antonín Dvořák":"<p>Antonín Dvořák (born 8 September 1841 in Nelahozeves; died 1 May 1904 in Prague) was a Czech composer of the Romantic period. His Symphony <em>From the New World</em> spread his reputation worldwide, and his other major works include a highly regarded Cello Concerto and the opera <em>Rusalka</em>. DoReDog has 1 Dvořák piece in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Anton%C3%ADn_Dvo%C5%99%C3%A1k\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","N. Rimsky-Korsakov":"<p>Nikolai Rimsky-Korsakov (born 18 March 1844 in Tikhvin; died 21 June 1908 near Luga) was a Russian composer and a member of the group known as The Five. His best-known orchestral works include <em>Capriccio Espagnol</em>, the <em>Russian Easter Festival Overture</em> and <em>Scheherazade</em>, while \"Flight of the Bumblebee\" from his opera <em>The Tale of Tsar Saltan</em> is his most famous excerpt in the West. DoReDog has 1 Rimsky-Korsakov piece in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Nikolai_Rimsky-Korsakov\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Georg Philipp Telemann":"<p>Georg Philipp Telemann (born 24 March 1681 in Magdeburg; died 25 June 1767 in Hamburg) was a German Baroque composer and multi-instrumentalist, one of the most prolific composers in history with more than 3,000 works. He served as musical director of Hamburg's five main churches from 1721; his notable works include <em>Tafelmusik</em> and the <em>Brockes Passion</em>. DoReDog has 2 Telemann pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Georg_Philipp_Telemann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Sigismond Thalberg":"<p>Sigismond Thalberg (born 8 January 1812 near Geneva; died 27 April 1871 in Naples) was an Austrian composer and one of the most distinguished virtuoso pianists of the 19th-century Romantic era. He was renowned for his fantasies on opera themes — especially his Op. 33 fantasy on Rossini's <em>Moses</em> — and for pioneering the \"three-hand effect\" at the piano. DoReDog has 2 Thalberg pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Sigismond_Thalberg\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Paul Wachs":"<p>Paul Wachs (born 19 September 1851 in Paris; died 6 July 1915 in Saint-Mandé) was a French Romantic-era composer, organist and pianist, most remembered for his salon piano pieces — his most famous being <em>Promenade à Âne</em>. He served as organist at the churches of Saint-Sulpice and Saint-Merri. DoReDog has 2 Wachs pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Paul_Wachs\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Jean-François Dandrieu":"<p>Jean-François Dandrieu (born c. 1682 in Paris; died 17 January 1738 in Paris) was a French Baroque composer and organist — a prodigy who reportedly performed for Louis XIV at the age of five. He is known for his harpsichord collections and organ noëls, and served as one of the four organists of the Chapelle royale. DoReDog has 2 Dandrieu pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Jean-Fran%C3%A7ois_Dandrieu\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Tom Turpin":"<p>Tom Turpin (born 18 November 1871 in Savannah, Georgia; died 13 August 1922) was an American ragtime composer, credited with the first published rag by an African American — his \"Harlem Rag\" of 1897. As owner of the Rosebud Café in St. Louis, he earned the title \"Father of St. Louis Ragtime.\" DoReDog has 2 Turpin pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Tom_Turpin\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Harriett Abrams":"<p>Harriett Abrams (born c. 1758 in Torquay; died 8 March 1821) was an English soprano and composer active in the late 18th century, particularly praised for performing Handel's repertoire. She composed popular songs including \"The Orphan's Prayer\" and \"Crazy Jane,\" and published canzonets, Scottish songs and glees. DoReDog has 2 Abrams pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Harriett_Abrams\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Joseph Barnby":"<p>Sir Joseph Barnby (born 12 August 1838 in York; died 28 January 1896 in London) was an English composer and conductor of the Romantic era, known for his songs and hymn tunes — including \"Sweet and Low\" (set to Tennyson) and \"Now the Day Is Over.\" He served as conductor of the Royal Albert Hall Choral Society and principal of the Guildhall School of Music. DoReDog has 2 Barnby pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Joseph_Barnby\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Mel Bonis":"<p>Mel Bonis was the pen name of Mélanie Hélène Bonis (born 21 January 1858 in Paris; died 18 March 1937 in Sarcelles), a French late-Romantic composer. She studied at the Paris Conservatoire under César Franck, alongside Claude Debussy, and composed over 300 works spanning piano, chamber, organ and vocal music. DoReDog has 2 Bonis pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Mel_Bonis\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Gabrielle Ferrari":"<p>Gabrielle Ferrari (née Colombari; born 14 September 1851 in Paris; died 4 July 1921 in Paris) was a French pianist and composer noted for her operas, who studied with Charles Gounod and Théodore Dubois. Her works include the opera <em>Le Cobzar</em>, which premiered in Monte Carlo. DoReDog has 2 Ferrari pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Gabrielle_Ferrari\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Eleanor Everest Freer":"<p>Eleanor Everest Freer (née Everest; born 14 May 1864 in Philadelphia; died 13 December 1942 in Chicago) was an American composer. She wrote eleven operas — including <em>Little Women</em> — and over 150 songs, and co-founded the Opera in Our Language Foundation in 1921 to promote American opera sung in English. DoReDog has 2 Freer pieces in letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Eleanor_Everest_Freer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Adolphe Adam":"<p>Adolphe Charles Adam was a French composer, teacher and music critic. A prolific composer for the theatre, he is best known today for his ballets Giselle (1841) and Le corsaire (1856), his operas Le postillon de Lonjumeau (1836) and Si j'étais roi (1852) and his Christmas carol \"Minuit, chrétiens!\".</p><p>DoReDog has <strong>1</strong> piece by Adolphe Adam (1803–1856) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Adolphe_Adam\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Adrian Willaert":"<p>Adrian Willaert was a Flemish composer of High Renaissance music. Mainly active in Italy, he was the founder of the Venetian School.</p><p>DoReDog has <strong>1</strong> piece by Adrian Willaert (1490–1562) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Adrian_Willaert\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Adrien-François Servais":"<p>Adrien-François Servais was one of the most influential cellists of the nineteenth century. He was born and died in what is now Halle, Belgium.</p><p>DoReDog has <strong>1</strong> piece by Adrien-François Servais (1807–1866) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Adrien-Fran%C3%A7ois_Servais\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Alessandro Scarlatti":"<p>Pietro Alessandro Gaspare Scarlatti was an Italian Baroque composer, known especially for his operas and chamber cantatas. He is considered the most important representative of the Neapolitan School of opera.</p><p>DoReDog has <strong>1</strong> piece by Alessandro Scarlatti (1660–1725) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Alessandro_Scarlatti\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Alexander Glazunov":"<p>Alexander Konstantinovich Glazunov was a Russian composer, music teacher, and conductor of the late Russian Romantic period. He was director of the Saint Petersburg Conservatory between 1905 and 1928 and was instrumental in the reorganization of the institute into the Petrograd Conservatory, then the Leningrad Conservatory, following the Bolshevik Revolution.</p><p>DoReDog has <strong>1</strong> piece by Alexander Glazunov (1865–1936) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Alexander_Glazunov\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Alexandre Guilmant":"<p>Félix-Alexandre Guilmant was a French organist and composer. He was the organist of La Trinité from 1871 until 1901.</p><p>DoReDog has <strong>1</strong> piece by Alexandre Guilmant (1837–1911) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Alexandre_Guilmant\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Alfred Cellier":"<p>Alfred Cellier was an English composer, orchestrator and conductor.</p><p>DoReDog has <strong>1</strong> piece by Alfred Cellier (1844–1891) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Alfred_Cellier\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Anatoly Lyadov":"<p>Anatoly Konstantinovich Lyadov was a Russian composer, teacher and conductor.</p><p>DoReDog has <strong>1</strong> piece by Anatoly Lyadov (1855–1914) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Anatoly_Lyadov\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Andreas Hammerschmidt":"<p>Andreas Hammerschmidt was a German Bohemian composer and organist of the early to middle Baroque era. He was one of the most significant and popular composers of sacred music in Germany in the middle 17th century.</p><p>DoReDog has <strong>1</strong> piece by Andreas Hammerschmidt (1611–1675) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Andreas_Hammerschmidt\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Antoine Busnois":"<p>Antoine Busnois was a French composer, singer and poet of early Renaissance music. Busnois and colleague Johannes Ockeghem were the leading European composers of the second half the 15th century and central figures of the early Franco-Flemish School.</p><p>DoReDog has <strong>1</strong> piece by Antoine Busnois (1430–1492) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Antoine_Busnois\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Anton Arensky":"<p>Anton Stepanovich Arensky was a Russian composer of Romantic classical music, pianist, conductor and professor of music. He is known especially for his chamber music, songs and piano works, and for a style often associated with the lyricism of Pyotr Ilyich Tchaikovsky.</p><p>DoReDog has <strong>1</strong> piece by Anton Arensky (1861–1906) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Anton_Arensky\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Anton Bruckner":"<p>Joseph Anton Bruckner was an Austrian composer and organist best known for his symphonies and sacred music, which includes Masses, Te Deum and motets. The symphonies are considered emblematic of the final stage of Austro-German Romanticism because of their rich harmonic language, strongly polyphonic character, and considerable length.</p><p>DoReDog has <strong>1</strong> piece by Anton Bruckner (1824–1896) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Anton_Bruckner\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Anton Hegner":"<p>Anton Hegner was a Danish cellist and composer.</p><p>DoReDog has <strong>1</strong> piece by Anton Hegner (1861–1915) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Anton_Hegner\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Anton Reicha":"<p>Anton Joseph Reicha (Rejcha) was a Bohemia-born, Bavarian-educated, later naturalized French composer and music theorist. A contemporary and friend of Beethoven, he is now best remembered for his substantial early contributions to the wind quintet literature and his role as teacher of pupils including Franz Liszt, Hector Berlioz and César Franck.</p><p>DoReDog has <strong>1</strong> piece by Anton Reicha (1770–1836) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Anton_Reicha\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Antonio Caldara":"<p>Antonio Caldara was an Italian Baroque composer.</p><p>DoReDog has <strong>1</strong> piece by Antonio Caldara (1670–1736) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Antonio_Caldara\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Balthasar Resinarius":"<p>Balthasar Resinarius was a German composer, and a Lutheran bishop, one of the first Lutherans in Bohemia.</p><p>DoReDog has <strong>1</strong> piece by Balthasar Resinarius (1485–1544) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Balthasar_Resinarius\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Béla Bartók":"<p>Béla Viktor János Bartók was a Hungarian composer, pianist and ethnomusicologist. He is considered one of the most important composers of the 20th century; he and Franz Liszt are regarded as Hungary's greatest composers.</p><p>DoReDog has <strong>1</strong> piece by Béla Bartók (1881–1945) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/B%C3%A9la_Bart%C3%B3k\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Carl Czerny":"<p>Carl Czerny was an Austrian composer, music educator, and pianist of Czech origin. His music spanned the late Classical and early Romantic eras.</p><p>DoReDog has <strong>1</strong> piece by Carl Czerny (1791–1857) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Carl_Czerny\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Charles Hunter":"<p>Charles H. Hunter was an American composer of ragtime music.</p><p>DoReDog has <strong>1</strong> piece by Charles Hunter (1876–1906) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Charles_Hunter_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","Charles William Glover":"<p>Charles William Glover was an English violinist and composer.</p><p>DoReDog has <strong>1</strong> piece by Charles William Glover (1806–1863) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Charles_William_Glover\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Charles Wood":"<p>Charles Wood was an Irish composer and teacher; his students included Ralph Vaughan Williams at Cambridge and Herbert Howells at the Royal College of Music. He is primarily remembered and performed as an Anglican church music composer, but he also wrote songs and chamber music, particularly for string quartet.</p><p>DoReDog has <strong>1</strong> piece by Charles Wood (1866–1926) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Charles_Wood_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","Charles-Marie Widor":"<p>Charles-Marie-Jean-Albert Widor was a French organist, composer and teacher of the late Romantic era. As a composer he is known for his ten organ symphonies, especially the toccata of his fifth organ symphony, which is frequently played as recessional music at weddings and other celebrations.</p><p>DoReDog has <strong>1</strong> piece by Charles-Marie Widor (1844–1937) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Charles-Marie_Widor\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Christian Ritter":"<p>Christian Ritter was a composer and organist of the North German organ school.</p><p>DoReDog has <strong>1</strong> piece by Christian Ritter (1645–1727) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Christian_Ritter\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Conradin Kreutzer":"<p>Conradin Kreutzer or Kreuzer was a German composer and conductor. His works include the operas Das Nachtlager in Granada and incidental music to Der Verschwender , both produced in 1834 in Vienna.</p><p>DoReDog has <strong>1</strong> piece by Conradin Kreutzer (1780–1849) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Conradin_Kreutzer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Cyril Rootham":"<p>Cyril Bradley Rootham was an English composer, educator and organist. His work at Cambridge University made him an influential figure in English music life.</p><p>DoReDog has <strong>1</strong> piece by Cyril Rootham (1875–1938) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Cyril_Rootham\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Daniel Godfrey":"<p>Daniel Godfrey was a British bandmaster, composer and arranger of compositions for military bands. He was for many years bandmaster of the Grenadier Guards.</p><p>DoReDog has <strong>1</strong> piece by Daniel Godfrey (1831–1903) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Daniel_Godfrey_(bandmaster\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","David Popper":"<p>David Popper was a Bohemian cellist and composer.</p><p>DoReDog has <strong>1</strong> piece by David Popper (1843–1913) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/David_Popper\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Delphin Strungk":"<p>Delphin Strungk was a German composer and organist associated with the North German school.</p><p>DoReDog has <strong>1</strong> piece by Delphin Strungk (1601–1694) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Delphin_Strungk\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Diego Ortiz":"<p>Diego Ortiz was a Spanish composer and music theorist in service to the viceroy of Naples ruled by the Spanish monarchs Charles V and Philip II. Ortiz published the first manual on ornamentation for bowed string instruments, and a large collection of sacred vocal compositions.</p><p>DoReDog has <strong>1</strong> piece by Diego Ortiz (1510–1570) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Diego_Ortiz\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Dora Pejačević":"<p>Countess Maria Theodora Paulina \"Dora\" Pejačević was a Croatian composer, pianist and violinist and one of the first composers to introduce the orchestral song to Croatian music. Her Symphony in F-sharp minor is considered by scholars to be the first modern symphony in Croatian music.</p><p>DoReDog has <strong>1</strong> piece by Dora Pejačević (1885–1923) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Dora_Peja%C4%8Devi%C4%87\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Elisabetta de Gambarini":"<p>Elisabetta de Gambarini was an English composer, singer, organist, harpsichordist, pianist, orchestral conductor and painter of the 18th century. Elisabetta's music is considered late Baroque and Classical music.</p><p>DoReDog has <strong>1</strong> piece by Elisabetta de Gambarini (1730–1765) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Elisabetta_de_Gambarini\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Émile Prudent":"<p>Émile Racine Gauthier Prudent was a French pianist and composer. His works number about seventy, and include a piano trio, a concerto-symphony, many character pieces, sets of variations, transcriptions and etudes, in addition to his celebrated fantasies on operatic airs.</p><p>DoReDog has <strong>1</strong> piece by Émile Prudent (1817–1863) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/%C3%89mile_Prudent\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Emmerich Kálmán":"<p>Emmerich Kálmán was a Hungarian composer of operettas and a prominent figure in the development of Viennese operetta in the 20th century. Among his most popular works are Die Csárdásfürstin (1915) and Gräfin Mariza (1924).</p><p>DoReDog has <strong>1</strong> piece by Emmerich Kálmán (1882–1953) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Emmerich_K%C3%A1lm%C3%A1n\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Engelbert Humperdinck":"<p>Engelbert Humperdinck was a German composer. He is known widely for his opera Hansel and Gretel (1893).</p><p>DoReDog has <strong>1</strong> piece by Engelbert Humperdinck (1854–1921) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Engelbert_Humperdinck_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","Ethel Barns":"<p>Ethel Barns was an English violinist, pianist and composer. She was born in London and entered the Royal Academy of Music at as a teenager, where she studied with Emile Sauret for violin, Ebenezer Prout for composition and Frederick Westlake for piano.</p><p>DoReDog has <strong>1</strong> piece by Ethel Barns (1880–1948) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ethel_Barns\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ethel Smyth":"<p>Dame Ethel Mary Smyth was an English composer and a member of the women's suffrage movement. Her compositions include songs, works for piano, chamber music, orchestral works, choral works and operas.</p><p>DoReDog has <strong>1</strong> piece by Ethel Smyth (1858–1944) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ethel_Smyth\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Faustina Hasse Hodges":"<p>Faustina Hasse Hodges was an English-American organist and composer.</p><p>DoReDog has <strong>1</strong> piece by Faustina Hasse Hodges (1823–1895) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Faustina_Hasse_Hodges\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Federico Ricci":"<p>Federico Ricci, was an Italian composer, particularly of operas. Born in Naples, he was the younger brother of Luigi Ricci, with whom he collaborated on several works.</p><p>DoReDog has <strong>1</strong> piece by Federico Ricci (1809–1877) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Federico_Ricci\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Feliks Janiewicz":"<p>Feliks Janiewicz, in English often Felix Yaniewicz was a Polish composer and violinist in exile.</p><p>DoReDog has <strong>1</strong> piece by Feliks Janiewicz (1762–1848) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Feliks_Janiewicz\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ferdinand Hiller":"<p>Ferdinand (von) Hiller was a German composer, conductor, pianist, writer and music director.</p><p>DoReDog has <strong>1</strong> piece by Ferdinand Hiller (1811–1885) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ferdinand_Hiller\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Fernando Sor":"<p>Fernando Sor was a Spanish classical guitarist and composer of the late Classical era and early Romantic era. Best known for writing solo classical guitar music, he also composed an opera, three symphonies, guitar duos, piano music, songs, a Mass, and at least two successful ballets: Cinderella, which received over one hundred performances, and Hercule et Omphale.</p><p>DoReDog has <strong>1</strong> piece by Fernando Sor (1778–1839) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Fernando_Sor\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Florian Hermann":"<p>Florian Hermann was a composer of German-Polish origin active in the Russian Empire. Although he authored many works, Hermann is primarily notable as an author of the melody used in the music for the well-known Russian song \"Dark eyes\".</p><p>DoReDog has <strong>1</strong> piece by Florian Hermann (1822–1892) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Florian_Hermann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Francesco Corteccia":"<p>Francesco Corteccia was an Italian composer, organist, and teacher of the Renaissance. Not only was he one of the best known of the early composers of madrigals, and an important native Italian composer during a period of domination by composers from the Low Countries, but he was the most prominent musician in Florence for several decades during the reign of Cosimo I de' Medici.</p><p>DoReDog has <strong>1</strong> piece by Francesco Corteccia (1502–1571) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Francesco_Corteccia\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Francisco Tárrega":"<p>Francisco de Asís Tárrega y Eixea was a Spanish composer and classical guitarist of the late Romantic period. He is known for such pieces as Capricho Árabe, Recuerdos de la Alhambra and Gran Vals.</p><p>DoReDog has <strong>1</strong> piece by Francisco Tárrega (1852–1909) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Francisco_T%C3%A1rrega\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","François Benoist":"<p>François Benoist was a French organist, pedagogue, and composer.</p><p>DoReDog has <strong>1</strong> piece by François Benoist (1794–1878) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Fran%C3%A7ois_Benoist\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","François Joseph Gossec":"<p>François-Joseph Gossec was a French composer of operas, string quartets, symphonies, and choral works.</p><p>DoReDog has <strong>1</strong> piece by François Joseph Gossec (1734–1829) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Fran%C3%A7ois-Joseph_Gossec\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Franz Behr":"<p>Franz Behr was a prolific, but minor, and now almost forgotten, German composer of songs and salon pieces for piano.</p><p>DoReDog has <strong>1</strong> piece by Franz Behr (1837–1898) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Franz_Behr\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Friedrich Kiel":"<p>Friedrich Kiel was a German composer and music educator.</p><p>DoReDog has <strong>1</strong> piece by Friedrich Kiel (1821–1885) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Friedrich_Kiel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Friedrich Wilhelm Marpurg":"<p>Friedrich Wilhelm Marpurg was a German music critic, music theorist and composer. Described as \"one of Germany's leading mid[18th-]century music critics,\" he was friendly and active with many figures of the Enlightenment.</p><p>DoReDog has <strong>1</strong> piece by Friedrich Wilhelm Marpurg (1718–1795) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Friedrich_Wilhelm_Marpurg\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Friedrich Wilhelm Zachow":"<p>Friedrich Wilhelm Zachow or Zachau was a German musician and composer of vocal and keyboard music.</p><p>DoReDog has <strong>1</strong> piece by Friedrich Wilhelm Zachow (1663–1712) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Friedrich_Wilhelm_Zachow\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Georg Muffat":"<p>Georg Muffat was a Baroque composer and organist. He is best known for the remarkably articulate and informative performance directions printed along with his collections of string pieces Florilegium Primum and Florilegium Secundum in 1695 and 1698.</p><p>DoReDog has <strong>1</strong> piece by Georg Muffat (1653–1704) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Georg_Muffat\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","George L. Cobb":"<p>George Linus Cobb was an American composer. He composed over 200 pieces of music, including ragtime, marches, and waltzes.</p><p>DoReDog has <strong>1</strong> piece by George L. Cobb (1886–1942) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/George_L._Cobb\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giacomo Carissimi":"<p>(Gian) Giacomo Carissimi was an Italian composer and music teacher. He is one of the most celebrated masters of the early Baroque or, more accurately, the Roman School of music.</p><p>DoReDog has <strong>1</strong> piece by Giacomo Carissimi (1605–1674) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giacomo_Carissimi\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giambattista De Curtis":"<p>Giambattista de Curtis was an Italian painter and poet remembered today for his song lyrics.</p><p>DoReDog has <strong>1</strong> piece by Giambattista De Curtis (1860–1926) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giambattista_De_Curtis\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giovanni Battista Pergolesi":"<p>Giovanni Battista Draghi, usually referred to as Giovanni Battista Pergolesi, was an Italian Baroque composer, violinist, and organist, leading exponent of the Baroque; he is considered one of the greatest Italian musicians of the first half of the 18th century and one of the most important representatives of the Neapolitan school.</p><p>DoReDog has <strong>1</strong> piece by Giovanni Battista Pergolesi (1710–1736) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giovanni_Battista_Pergolesi\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giovanni Battista Pescetti":"<p>Giovanni Battista Pescetti was an organist, harpsichordist, and composer known primarily for his operas and keyboard sonatas. Musicologist and University of California, Santa Barbara professor John E. Gillespie wrote that Pescetti \"stylistically stands as a bridge between Alberti and Domenico Scarlatti\".</p><p>DoReDog has <strong>1</strong> piece by Giovanni Battista Pescetti (1704–1766) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giovanni_Battista_Pescetti\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giovanni Gabrieli":"<p>Giovanni Gabrieli was an Italian composer and organist. He was one of the most influential musicians of his time, and represents the culmination of the style of the Venetian School, at the time of the shift from Renaissance to Baroque idioms.</p><p>DoReDog has <strong>1</strong> piece by Giovanni Gabrieli (1557–1612) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giovanni_Gabrieli\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giovanni Maria Bononcini":"<p>Giovanni Maria Bononcini was an Italian violinist and composer, the father of a musical dynasty.</p><p>DoReDog has <strong>1</strong> piece by Giovanni Maria Bononcini (1642–1678) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giovanni_Maria_Bononcini\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Girolamo Frescobaldi":"<p>Girolamo Alessandro Frescobaldi was an Italian composer and virtuoso keyboard player. Born in the Duchy of Ferrara, he was one of the most important composers of keyboard music in the late Renaissance and early Baroque periods.</p><p>DoReDog has <strong>1</strong> piece by Girolamo Frescobaldi (1583–1643) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Girolamo_Frescobaldi\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giulio Caccini":"<p>Giulio Romolo Caccini was an Italian composer, teacher, singer, instrumentalist and writer of the late Renaissance and early Baroque eras. He was one of the founders of the genre of opera, and one of the most influential creators of the new Baroque style.</p><p>DoReDog has <strong>1</strong> piece by Giulio Caccini (1551–1618) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giulio_Caccini\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Giuseppe Baini":"<p>Abbate Giuseppe Baini was an Italian priest, music critic, conductor, and composer of church music.</p><p>DoReDog has <strong>1</strong> piece by Giuseppe Baini (1775–1844) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Giuseppe_Baini\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Guillaume Dufay":"<p>Guillaume Du Fay was a composer and music theorist of early Renaissance music, who is variously described as French or Franco-Flemish. Considered the leading European composer of his time, his music was widely performed and reproduced.</p><p>DoReDog has <strong>1</strong> piece by Guillaume Dufay (1397–1474) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Guillaume_Du_Fay\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Hans Georg Nägeli":"<p>Hans Georg Nägeli was a composer and music publisher.</p><p>DoReDog has <strong>1</strong> piece by Hans Georg Nägeli (1773–1836) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Hans_Georg_N%C3%A4geli\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Harry J. Lincoln":"<p>Harry James Lincoln, also known as Harry Jay Lincoln, was a music composer from Williamsport, Pennsylvania.</p><p>DoReDog has <strong>1</strong> piece by Harry J. Lincoln (1878–1937) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Harry_J._Lincoln\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Hector Berlioz":"<p>Louis-Hector Berlioz was a French Romantic composer, conductor and critic. His output includes orchestral works such as the Symphonie fantastique and Harold in Italy, choral pieces including the Requiem and L'Enfance du Christ, his three operas Benvenuto Cellini, Les Troyens and Béatrice et Bénédict, and works of hybrid genres such as the \"dramatic symphony\" Roméo et Juliette and the \"dramatic legend\" La Damnation de Faust.</p><p>DoReDog has <strong>1</strong> piece by Hector Berlioz (1803–1869) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Hector_Berlioz\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Heinrich Isaac":"<p>Heinrich Isaac was a Netherlandish composer of south Netherlandish origin during the Renaissance era. He wrote masses, motets, songs, and instrumental music.</p><p>DoReDog has <strong>1</strong> piece by Heinrich Isaac (1450–1517) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Heinrich_Isaac\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Heinrich Schütz":"<p>Heinrich Schütz was a German early Baroque composer and organist, generally regarded as the most important German composer before Johann Sebastian Bach and one of the most important composers of the 17th century. He is credited with bringing the Italian style to Germany and continuing its evolution from the Renaissance into the early Baroque.</p><p>DoReDog has <strong>1</strong> piece by Heinrich Schütz (1585–1672) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Heinrich_Sch%C3%BCtz\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Helen Hopekirk":"<p>Helen Hopekirk was a Scottish-born American pianist and composer, who after the age of 40, lived and worked in Boston, Massachusetts.</p><p>DoReDog has <strong>1</strong> piece by Helen Hopekirk (1856–1945) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Helen_Hopekirk\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Henri Desmarets":"<p>Henri Desmarets was a French composer of the Baroque period primarily known for his stage works, although he also composed sacred music as well as secular cantatas, songs and instrumental works.</p><p>DoReDog has <strong>1</strong> piece by Henri Desmarets (1661–1741) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Henri_Desmarets\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Henry Carey":"<p>Henry Carey was an English poet, dramatist and composer. He is remembered as an anti-Walpolean satirist and also as a patriot.</p><p>DoReDog has <strong>1</strong> piece by Henry Carey (1687–1743) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Henry_Carey_(writer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","Henry Lawes":"<p>Henry Lawes was the leading English songwriter of the mid-17th century. He was elder brother of fellow composer William Lawes.</p><p>DoReDog has <strong>1</strong> piece by Henry Lawes (1596–1662) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Henry_Lawes\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ignaz Moscheles":"<p>Isaac Ignaz Moscheles was a Bohemian piano virtuoso and composer. He was based initially in London and later in Leipzig, where he joined his friend and sometime pupil Felix Mendelssohn as professor of piano in the Conservatory.</p><p>DoReDog has <strong>1</strong> piece by Ignaz Moscheles (1794–1870) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ignaz_Moscheles\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ignaz Pleyel":"<p>Ignaz (Ignace) Joseph Pleyel was an Austrian composer, music publisher and piano builder of the Classical period. He grew up in Austria, and was educated there; in his mid-twenties he moved to France, and was based in France for the rest of his life.</p><p>DoReDog has <strong>1</strong> piece by Ignaz Pleyel (1757–1831) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ignaz_Pleyel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Jacques Blumenthal":"<p>Jacques Blumenthal was a German pianist and composer. Born \"Jakob\" in Hamburg, he began his musical studies at an early age, receiving instruction from Friedrich Wilhelm Grund, Carl Maria von Bocklet, and Simon Sechter.</p><p>DoReDog has <strong>1</strong> piece by Jacques Blumenthal (1829–1908) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Jacques_Blumenthal\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Joachim Raff":"<p>Joseph Joachim Raff was a Swiss composer, pedagogue and pianist.</p><p>DoReDog has <strong>1</strong> piece by Joachim Raff (1822–1882) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Joachim_Raff\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Abraham Peter Schulz":"<p>Johann Abraham Peter Schulz was a German musician. He is best known as the composer of the melody for Matthias Claudius's poems \"Der Mond ist aufgegangen\" and \"Wir pflügen und wir streuen\", and the Christmas carol \"Ihr Kinderlein kommet\".</p><p>DoReDog has <strong>1</strong> piece by Johann Abraham Peter Schulz (1747–1800) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Abraham_Peter_Schulz\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann André":"<p>Johann André was a German musician, composer and music publisher of the Classical period. He was born and died in Offenbach am Main.</p><p>DoReDog has <strong>1</strong> piece by Johann André (1741–1799) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Andr%C3%A9\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Baptist Cramer":"<p>Johann Baptist Cramer was an English pianist, composer and music publisher of German origin, born in the Holy Roman Empire. He was the son of Wilhelm Cramer, a famous London violinist and conductor, one of a numerous family who were identified with the progress of music during the 18th and 19th centuries.</p><p>DoReDog has <strong>1</strong> piece by Johann Baptist Cramer (1771–1858) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Baptist_Cramer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Baptist Vanhal":"<p>Johann Baptist Wanhal was a Czech composer of the Classical period. He was born in Nechanice, Bohemia, and died in Vienna.</p><p>DoReDog has <strong>1</strong> piece by Johann Baptist Vanhal (1739–1813) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Baptist_Wanhal\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Christian Bach":"<p>Johann Christian Bach was a German composer of the Classical era and the youngest son of Johann Sebastian Bach.</p><p>DoReDog has <strong>1</strong> piece by Johann Christian Bach (1735–1782) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Christian_Bach\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Christoph Pezel":"<p>Johann Christoph Pezel was a German violinist, trumpeter, and composer.</p><p>DoReDog has <strong>1</strong> piece by Johann Christoph Pezel (1639–1694) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Christoph_Pezel\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Ernst Eberlin":"<p>Johann Ernst Eberlin was a German composer and organist whose works bridge the baroque and classical eras. He was a composer of church organ and choral music.</p><p>DoReDog has <strong>1</strong> piece by Johann Ernst Eberlin (1702–1762) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Ernst_Eberlin\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Friedrich Alberti":"<p>Johann Friedrich Alberti was a German composer and organist.</p><p>DoReDog has <strong>1</strong> piece by Johann Friedrich Alberti (1642–1710) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Friedrich_Alberti\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Heinrich Buttstett":"<p>Johann Heinrich Buttstett was a German Baroque organist and composer. Although he was Johann Pachelbel's most important pupil and one of the last major exponents of the south German organ tradition, Buttstett is best remembered for a dispute with Johann Mattheson.</p><p>DoReDog has <strong>1</strong> piece by Johann Heinrich Buttstett (1666–1727) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Heinrich_Buttstett\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Mattheson":"<p>Johann Mattheson was a German composer, critic, lexicographer and music theorist. His writings on the late Baroque and early Classical period were highly influential, specifically, \"his biographical and theoretical works were widely disseminated and served as the source for all subsequent lexicographers and historians\".</p><p>DoReDog has <strong>1</strong> piece by Johann Mattheson (1681–1764) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Mattheson\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Johann Rosenmüller":"<p>Johann Rosenmüller was a German Baroque composer, who played a part in transmitting Italian musical styles to the north.</p><p>DoReDog has <strong>1</strong> piece by Johann Rosenmüller (1619–1684) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Johann_Rosenm%C3%BCller\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","John Dowland":"<p>John Dowland was an English Renaissance composer, lutenist, and singer. He is best known today for his melancholy songs such as \"Come, heavy sleep\", \"Come again\", \"Flow my tears\", \"I saw my Lady weepe\", \"Now o now I needs must part\", and \"In darkness let me dwell\".</p><p>DoReDog has <strong>1</strong> piece by John Dowland (1563–1626) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/John_Dowland\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","John Field":"<p>John Field was an Irish pianist, composer and teacher widely credited as the inventor of the nocturne. While many of his contemporaries wrote in a similar style, Field was the first to use the term to apply to a character piece featuring a cantabile melody over an arpeggiated accompaniment.</p><p>DoReDog has <strong>1</strong> piece by John Field (1782–1837) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/John_Field_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","John Hill Hewitt":"<p>John Hill Hewitt was an American composer, playwright, and poet. He is best known for his songs about the American South, including \"A Minstrel's Return from the War\", \"The Soldier's Farewell\", \"The Stonewall Quickstep\", and \"Somebody's Darling\".</p><p>DoReDog has <strong>1</strong> piece by John Hill Hewitt (1801–1890) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/John_Hill_Hewitt\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","John Stafford Smith":"<p>John Stafford Smith was an English composer, church organist, and early musicologist. He was one of the first serious collectors of manuscripts of works by Johann Sebastian Bach and a friend of his son Johann Christian Bach.</p><p>DoReDog has <strong>1</strong> piece by John Stafford Smith (1750–1836) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/John_Stafford_Smith\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Joseph Gungl":"<p>Joseph Gungl, correct: Josef Gung'l, was a Hungarian composer, bandmaster, and conductor. He was soprano Virginia Naumann-Gungl's father.</p><p>DoReDog has <strong>1</strong> piece by Joseph Gungl (1810–1889) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Joseph_Gungl\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Joseph-Hector Fiocco":"<p>Joseph-Hector Fiocco, born in Brussels, was a composer and harpsichordist of the late Baroque period.</p><p>DoReDog has <strong>1</strong> piece by Joseph-Hector Fiocco (1703–1741) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Joseph-Hector_Fiocco\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Jules Massenet":"<p>Jules Émile Frédéric Massenet was a French composer of the Romantic era best known for his operas, of which he wrote more than thirty. The two most frequently staged are Manon (1884) and Werther (1892).</p><p>DoReDog has <strong>1</strong> piece by Jules Massenet (1842–1912) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Jules_Massenet\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Karol Kurpiński":"<p>Karol Kazimierz Kurpiński was a Polish composer, conductor and pedagogue. He was a representative of late classicism and early romanticism as well as being a member of the Warsaw Society of Friends of Learning.</p><p>DoReDog has <strong>1</strong> piece by Karol Kurpiński (1785–1857) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Karol_Kurpi%C5%84ski\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Léon Boëllmann":"<p>Léon Boëllmann was a French composer, known for a small number of compositions for organ. His best-known composition is Suite gothique (1895), which is a staple of the organ repertoire, especially its concluding Toccata.</p><p>DoReDog has <strong>1</strong> piece by Léon Boëllmann (1862–1897) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/L%C3%A9on_Bo%C3%ABllmann\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Louis Lacombe":"<p>Pierre Louis Trouillon-Lacombe was a French pianist and composer.</p><p>DoReDog has <strong>1</strong> piece by Louis Lacombe (1818–1884) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Louis_Lacombe\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Louis Marie François Andlauer":"<p>Louis Andlauer was a French composer and organist.</p><p>DoReDog has <strong>1</strong> piece by Louis Marie François Andlauer (1876–1915) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Louis_Andlauer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Louis Spohr":"<p>Louis Spohr, baptized Ludewig Spohr, later often in the modern German form of the name Ludwig, was a German composer, violinist and conductor.</p><p>DoReDog has <strong>1</strong> piece by Louis Spohr (1784–1859) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Louis_Spohr\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Louis Théodore Gouvy":"<p>Louis Théodore Gouvy was a French/German composer.</p><p>DoReDog has <strong>1</strong> piece by Louis Théodore Gouvy (1819–1898) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Th%C3%A9odore_Gouvy\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Louise Farrenc":"<p>Louise Farrenc was a French composer, virtuoso pianist and teacher of the Romantic period. Her compositions include three symphonies, a few choral works, numerous chamber pieces and a wide variety of piano music.</p><p>DoReDog has <strong>1</strong> piece by Louise Farrenc (1804–1875) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Louise_Farrenc\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Louise Reichardt":"<p>Louise Reichardt or Luise Reichardt was a German composer and choral conductor. Her German songs, or Lieder, were written in an accessible style akin to folk music and were popular.</p><p>DoReDog has <strong>1</strong> piece by Louise Reichardt (1779–1826) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Louise_Reichardt\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Lowell Mason":"<p>Lowell Mason was an American music director and banker who was a leading figure in 19th-century American church music. Lowell composed over 1,600 hymn tunes, many of which are often sung today.</p><p>DoReDog has <strong>1</strong> piece by Lowell Mason (1792–1872) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Lowell_Mason\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ludwig Minkus":"<p>Ludwig Minkus, also known as Léon Fyodorovich Minkus, was an Austrian composer of ballet music, a violinist and teacher of music.</p><p>DoReDog has <strong>1</strong> piece by Ludwig Minkus (1826–1917) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ludwig_Minkus\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ludwig Senfl":"<p>Ludwig Senfl was a Swiss composer of the Renaissance, active in Germany. He was the most famous pupil of Heinrich Isaac, was music director to the court of Maximilian I, Holy Roman Emperor, and was an influential figure in the development of the Franco-Flemish polyphonic style in Germany.</p><p>DoReDog has <strong>1</strong> piece by Ludwig Senfl (1490–1543) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ludwig_Senfl\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Luigi Denza":"<p>Luigi Denza was an Italian composer.</p><p>DoReDog has <strong>1</strong> piece by Luigi Denza (1846–1922) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Luigi_Denza\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Luis Venegas de Henestrosa":"<p>Luis Venegas de Henestrosa was a Spanish composer of the 16th century active during the Spanish Golden Age. Few details are known about his life and he is most remembered for publishing Libro de cifra nueva para tecla, Arpa y Vihuela, a collection of over two hundred pieces for harp, keyboard and vihuela.</p><p>DoReDog has <strong>1</strong> piece by Luis Venegas de Henestrosa (1510–1571) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Luis_Venegas_de_Henestrosa\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Marin Marais":"<p>Marin Marais was a French composer and viol player of the middle Baroque era. He studied composition with Jean-Baptiste Lully, often conducting his operas, and with the master of the bass viol Monsieur de Sainte-Colombe for six months.</p><p>DoReDog has <strong>1</strong> piece by Marin Marais (1656–1728) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Marin_Marais\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Mauro Giuliani":"<p>Mauro Giuseppe Sergio Pantaleo Giuliani was an Italian guitarist, cellist, singer, and composer. He was a leading guitar virtuoso of the early 19th century.</p><p>DoReDog has <strong>1</strong> piece by Mauro Giuliani (1781–1829) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Mauro_Giuliani\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Nicola De Giosa":"<p>Nicola De Giosa was an Italian composer and conductor active in Naples. He composed numerous operas, the most successful of which, Don Checco and Napoli di carnevale, were in the Neapolitan opera buffa genre.</p><p>DoReDog has <strong>1</strong> piece by Nicola De Giosa (1820–1885) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Nicola_De_Giosa\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Nicolas Chédeville":"<p>Nicolas Chédeville was a French composer, musette player and musette maker.</p><p>DoReDog has <strong>1</strong> piece by Nicolas Chédeville (1705–1782) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Nicolas_Ch%C3%A9deville\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Nicolas de Grigny":"<p>Nicolas de Grigny was a French organist and composer. He died young and left behind a single collection of organ music, and an Ouverture for harpsichord.</p><p>DoReDog has <strong>1</strong> piece by Nicolas de Grigny (1672–1703) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Nicolas_de_Grigny\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Norbert Burgmüller":"<p>August Joseph Norbert Burgmüller was a German composer, renowned for his contributions during the nascent stages of the Romantic Era. His oeuvre, albeit cut tragically short due to his untimely drowning at the age of 26, continues to resonate in the annals of classical music.</p><p>DoReDog has <strong>1</strong> piece by Norbert Burgmüller (1810–1836) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Norbert_Burgm%C3%BCller\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Orlande de Lassus":"<p>Orlando di Lasso was a composer of the late Renaissance. The chief representative of the mature polyphonic style in the Franco-Flemish school, Lasso stands with William Byrd, Giovanni Pierluigi da Palestrina, and Tomás Luis de Victoria as one of the leading composers of the later Renaissance.</p><p>DoReDog has <strong>1</strong> piece by Orlande de Lassus (1532–1594) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Orlando_di_Lasso\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Pablo de Sarasate":"<p>Pablo Martín Melitón de Sarasate y Navascués was a Spanish virtuoso violinist, composer, and conductor of the Romantic period. His best known works include Zigeunerweisen, the Spanish Dances, and the Carmen Fantasy.</p><p>DoReDog has <strong>1</strong> piece by Pablo de Sarasate (1844–1908) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Pablo_de_Sarasate\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Paul Dukas":"<p>Paul Abraham Dukas was a French composer, critic, scholar and teacher. A studious man of retiring personality, he was intensely self-critical and abandoned and destroyed many of his compositions.</p><p>DoReDog has <strong>1</strong> piece by Paul Dukas (1865–1935) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Paul_Dukas\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Ruggiero Giovannelli":"<p>Ruggiero Giovannelli was an Italian composer of the late Renaissance and early Baroque eras. He was a member of the Roman School, and succeeded Palestrina at St. Peter's.</p><p>DoReDog has <strong>1</strong> piece by Ruggiero Giovannelli (1560–1625) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Ruggiero_Giovannelli\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Saverio Mercadante":"<p>Giuseppe Saverio Raffaele Mercadante was an Italian composer, particularly of operas. While Mercadante may not have retained the international celebrity of Vincenzo Bellini, Gaetano Donizetti or Gioachino Rossini beyond his own lifetime, he composed as prolifically as any of them, and his development of operatic structures, melodic styles and orchestration contributed significantly to the foundations upon which Giuseppe Verdi built his dramatic technique.</p><p>DoReDog has <strong>1</strong> piece by Saverio Mercadante (1795–1870) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Saverio_Mercadante\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Sydney Smith":"<p>Sydney Smith was an English pianist and composer in Victorian England.</p><p>DoReDog has <strong>1</strong> piece by Sydney Smith (1839–1889) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Sydney_Smith_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","Tarquinio Merula":"<p>Tarquinio Merula was an Italian composer, organist, and violinist of the early Baroque era. Although mainly active in Cremona, stylistically he was a member of the Venetian school.</p><p>DoReDog has <strong>1</strong> piece by Tarquinio Merula (1595–1665) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Tarquinio_Merula\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Tekla Bądarzewska-Baranowska":"<p>Tekla Bądarzewska-Baranowska, also known as Tekla Bądarzewska was a Polish composer and pianist. She composed mainly for the piano and is internationally known for her composition A Maiden's Prayer.</p><p>DoReDog has <strong>1</strong> piece by Tekla Bądarzewska-Baranowska (1823–1861) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Tekla_B%C4%85darzewska-Baranowska\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Teresa Carreño":"<p>María Teresa Gertrudis de Jesús Carreño García was a Venezuelan pianist, composer, soprano, and conductor. Over the course of her 54-year concert career, she became an internationally renowned virtuoso pianist and was often referred to as the \"Valkyrie of the Piano\".</p><p>DoReDog has <strong>1</strong> piece by Teresa Carreño (1853–1917) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Teresa_Carre%C3%B1o\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Theodor Leschetizky":"<p>Theodor Leschetizky was a Polish pianist, professor, and composer active in Austria-Hungary. He was born in Łańcut in the Kingdom of Galicia and Lodomeria, then a crown land of the Habsburg domain.</p><p>DoReDog has <strong>1</strong> piece by Theodor Leschetizky (1830–1915) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Theodor_Leschetizky\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Thomas Crecquillon":"<p>Thomas Crecquillon or Créquillon was a Franco-Flemish school composer of the Renaissance. While his place of birth is unknown, it was probably within the region loosely known at the time as the Low Countries, and he probably died at Béthune.</p><p>DoReDog has <strong>1</strong> piece by Thomas Crecquillon (1505–1557) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Thomas_Crecquillon\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Thomas Ravenscroft":"<p>Thomas Ravenscroft was an English musician, theorist and editor, notable as a composer of rounds and catches, and especially for compiling collections of English folk music and a collection of psalm settings.</p><p>DoReDog has <strong>1</strong> piece by Thomas Ravenscroft (1592–1635) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Thomas_Ravenscroft\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Thomas Tallis":"<p>Thomas Tallis was an English composer of High Renaissance music. His compositions are primarily vocal, and he occupies a primary place in anthologies of English choral music.</p><p>DoReDog has <strong>1</strong> piece by Thomas Tallis (1505–1585) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Thomas_Tallis\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Vasily Kalinnikov":"<p>Vasily Sergeyevich Kalinnikov was a Russian composer. His body of work consists of two symphonies, several additional orchestral works, and numerous songs, all of them imbued with characteristics of folksong.</p><p>DoReDog has <strong>1</strong> piece by Vasily Kalinnikov (1866–1901) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Vasily_Kalinnikov\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","Vincenzo Galilei":"<p>Vincenzo Galilei was an Italian lutenist, composer, and music theorist. His children included the astronomer and physicist Galileo Galilei and the lute virtuoso and composer Michelagnolo Galilei.</p><p>DoReDog has <strong>1</strong> piece by Vincenzo Galilei (1520–1591) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/Vincenzo_Galilei\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","William Byrd":"<p>William Byrd was an English Renaissance composer. Considered among the greatest composers of the Renaissance, he had a profound influence on composers both from his native country and on the Continent.</p><p>DoReDog has <strong>1</strong> piece by William Byrd (1543–1623) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/William_Byrd\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>","William Mundy":"<p>William Mundy was a Renaissance English composer of sacred music and father of composer John Mundy. Over four hundred years after his death, William Mundy's music is still performed and recorded.</p><p>DoReDog has <strong>1</strong> piece by William Mundy (1528–1591) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/William_Mundy_(composer\" target=\"_blank\" rel=\"noopener\">Wikipedia</a>)</em></p>","William Shield":"<p>William Shield was an English composer, violinist and violist. His music earned the respect of Haydn and Beethoven.</p><p>DoReDog has <strong>1</strong> piece by William Shield (1748–1829) in colour-coded letter notes. <em>Source: <a href=\"https://en.wikipedia.org/wiki/William_Shield\" target=\"_blank\" rel=\"noopener\">Wikipedia</a></em></p>"};
